/* DAWAH X — ahmad, অধ্যায় 83 · খণ্ড 83 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][83]=[[16401,16401,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْفَيْضِ ‏ ‏عَنْ ‏ ‏سُلَيْمِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏يَسِيرُ بِأَرْضِ ‏ ‏الرُّومِ ‏ ‏وَكَانَ بَيْنَهُمْ وَبَيْنَهُ ‏ ‏أَمَدٌ ‏ ‏فَأَرَادَ أَنْ يَدْنُوَ مِنْهُمْ فَإِذَا انْقَضَى ‏ ‏الْأَمَدُ ‏ ‏غَزَاهُمْ فَإِذَا شَيْخٌ عَلَى دَابَّةٍ يَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ وَفَاءٌ لَا غَدْرٌ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ بَيْنَهُ وَبَيْنَ قَوْمٍ عَهْدٌ فَلَا يَحِلَّنَّ عُقْدَةً وَلَا يَشُدَّهَا حَتَّى يَنْقَضِيَ ‏ ‏أَمَدُهَا ‏ ‏أَوْ ‏ ‏يَنْبِذَ ‏ ‏إِلَيْهِمْ عَلَى سَوَاءٍ فَبَلَغَ ذَلِكَ ‏ ‏مُعَاوِيَةَ ‏ ‏فَرَجَعَ وَإِذَا الشَّيْخُ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏","","",""],[16402,16402,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي عَمْرٍو السَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ الدِّمَشْقِيِّ ‏ ‏وَعَمْرِو بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏حَدِيثِ ‏ ‏عَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏رَغِبْتُ عَنْ آلِهَةِ قَوْمِي فِي الْجَاهِلِيَّةِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ فَسَأَلْتُ عَنْهُ فَوَجَدْتُهُ مُسْتَخْفِيًا بِشَأْنِهِ فَتَلَطَّفْتُ لَهُ حَتَّى دَخَلْتُ عَلَيْهِ فَسَلَّمْتُ عَلَيْهِ فَقُلْتُ لَهُ مَا أَنْتَ فَقَالَ نَبِيٌّ فَقُلْتُ وَمَا النَّبِيُّ فَقَالَ رَسُولُ اللَّهِ فَقُلْتُ وَمَنْ أَرْسَلَكَ قَالَ اللَّهُ عَزَّ وَجَلَّ قُلْتُ بِمَاذَا أَرْسَلَكَ فَقَالَ ‏ ‏بِأَنْ ‏ ‏تُوصَلَ ‏ ‏الْأَرْحَامُ ‏ ‏وَتُحْقَنَ الدِّمَاءُ وَتُؤَمَّنَ السُّبُلُ وَتُكَسَّرَ الْأَوْثَانُ وَيُعْبَدَ اللَّهُ وَحْدَهُ لَا يُشْرَكُ بِهِ شَيْءٌ قُلْتُ نِعْمَ مَا أَرْسَلَكَ بِهِ وَأُشْهِدُكَ أَنِّي قَدْ آمَنْتُ بِكَ وَصَدَّقْتُكَ أَفَأَمْكُثُ مَعَكَ أَمْ مَا ‏ ‏تَرَى فَقَالَ قَدْ ‏ ‏تَرَى كَرَاهَةَ النَّاسِ لِمَا جِئْتُ بِهِ فَامْكُثْ فِي أَهْلِكَ فَإِذَا سَمِعْتُمْ بِي قَدْ خَرَجْتُ مَخْرَجِي فَأْتِنِي ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[16403,16403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏السَّرِيُّ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ زِيَادٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَسَةَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَضْمَضَ وَاسْتَنْشَقَ فِي رَمَضَانَ ‏","","",""],[16404,16404,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ مَنْ أَسْلَمَ ‏ ‏يَعْنِي مَعَكَ فَقَالَ حُرٌّ وَعَبْدٌ ‏ ‏يَعْنِي ‏ ‏أَبَا بَكْرٍ ‏ ‏وَبِلَالًا ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي مِمَّا ‏ ‏تَعْلَمُ وَأَجْهَلُ ‏ ‏هَلْ مِنْ السَّاعَاتِ سَاعَةٌ أَفْضَلُ مِنْ الْأُخْرَى قَالَ جَوْفُ اللَّيْلِ الْآخِرُ أَفْضَلُ فَإِنَّهَا مَشْهُودَةٌ مُتَقَبَّلَةٌ حَتَّى تُصَلِّيَ الْفَجْرَ ثُمَّ انْهَهُ حَتَّى تَطْلُعَ الشَّمْسُ مَا دَامَتْ ‏ ‏كَالْحَجَفَةِ ‏ ‏حَتَّى تَنْتَشِرَ فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَيَسْجُدُ لَهَا الْكُفَّارُ ثُمَّ تُصَلِّي فَإِنَّهَا مَشْهُودَةٌ مُتَقَبَّلَةٌ حَتَّى يَسْتَوِيَ الْعَمُودُ عَلَى ظِلِّهِ ثُمَّ انْهَهُ فَإِنَّهَا سَاعَةٌ ‏ ‏تُسْجَرُ ‏ ‏فِيهَا الْجَحِيمُ فَإِذَا زَالَتْ فَصَلِّ فَإِنَّهَا مَشْهُودَةٌ مُتَقَبَّلَةٌ حَتَّى تُصَلِّيَ الْعَصْرَ ثُمَّ انْهَهُ حَتَّى تَغْرُبَ الشَّمْسُ فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَيَسْجُدُ لَهَا الْكُفَّارُ ‏ ‏وَكَانَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏يَقُولُ ‏ ‏أَنَا رُبُعُ الْإِسْلَامِ ‏ ‏وَكَانَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏يُصَلِّي بَعْدَ الْعَصْرِ رَكْعَتَيْنِ ‏","","",""],[16405,16405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ يَعْنِي ابْنَ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏شَدَّادُ بْنُ عَبْدِ اللَّهِ الدِّمَشْقِيُّ ‏ ‏وَكَانَ قَدْ أَدْرَكَ نَفَرًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏يَا ‏ ‏عَمْرُو بْنَ عَبَسَةَ ‏ ‏صَاحِبَ الْعَقْلِ عَقْلِ ‏ ‏الصَّدَقَةِ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏بِأَيِّ شَيْءٍ ‏ ‏تَدَّعِي أَنَّكَ ‏ ‏رُبُعُ ‏ ‏الْإِسْلَامِ قَالَ إِنِّي كُنْتُ فِي الْجَاهِلِيَّةِ أَرَى النَّاسَ عَلَى ضَلَالَةٍ وَلَا أَرَى الْأَوْثَانَ شَيْئًا ثُمَّ سَمِعْتُ عَنْ رَجُلٍ يُخْبِرُ أَخْبَارَ ‏ ‏مَكَّةَ ‏ ‏وَيُحَدِّثُ أَحَادِيثَ فَرَكِبْتُ ‏ ‏رَاحِلَتِي ‏ ‏حَتَّى قَدِمْتُ ‏ ‏مَكَّةَ ‏ ‏فَإِذَا أَنَا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْتَخْفٍ ‏ ‏وَإِذَا قَوْمُهُ عَلَيْهِ ‏ ‏جُرَآءُ ‏ ‏فَتَلَطَّفْتُ لَهُ فَدَخَلْتُ عَلَيْهِ فَقُلْتُ مَا أَنْتَ قَالَ أَنَا نَبِيُّ اللَّهِ فَقُلْتُ وَمَا نَبِيُّ اللَّهِ قَالَ رَسُولُ اللَّهِ قَالَ قُلْتُ ‏ ‏آللَّهُ أَرْسَلَكَ قَالَ نَعَمْ قُلْتُ بِأَيِّ شَيْءٍ أَرْسَلَكَ قَالَ بِأَنْ يُوَحَّدَ اللَّهُ وَلَا يُشْرَكَ بِهِ شَيْءٌ وَكَسْرِ الْأَوْثَانِ ‏ ‏وَصِلَةِ ‏ ‏الرَّحِمِ ‏ ‏فَقُلْتُ لَهُ مَنْ مَعَكَ عَلَى هَذَا قَالَ حُرٌّ وَعَبْدٌ ‏ ‏أَوْ عَبْدٌ وَحُرٌّ ‏ ‏وَإِذَا مَعَهُ ‏ ‏أَبُو بَكْرِ بْنُ أَبِي قُحَافَةَ ‏ ‏وَبِلَالٌ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏قُلْتُ إِنِّي مُتَّبِعُكَ قَالَ إِنَّكَ لَا تَسْتَطِيعُ ذَلِكَ يَوْمَكَ هَذَا وَلَكِنْ ارْجِعْ إِلَى أَهْلِكَ فَإِذَا سَمِعْتَ بِي قَدْ ظَهَرْتُ فَالْحَقْ بِي قَالَ فَرَجَعْتُ إِلَى أَهْلِي وَقَدْ أَسْلَمْتُ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهَاجِرًا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَجَعَلْتُ أَتَخَبَّرُ الْأَخْبَارَ حَتَّى جَاءَ ‏ ‏رَكَبَةٌ ‏ ‏مِنْ ‏ ‏يَثْرِبَ ‏ ‏فَقُلْتُ مَا هَذَا الْمَكِّيُّ الَّذِي أَتَاكُمْ قَالُوا أَرَادَ قَوْمُهُ قَتْلَهُ فَلَمْ يَسْتَطِيعُوا ذَلِكَ وَحِيلَ بَيْنَهُمْ وَبَيْنَهُ وَتَرَكْنَا النَّاسَ سِرَاعًا قَالَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏فَرَكِبْتُ ‏ ‏رَاحِلَتِي ‏ ‏حَتَّى قَدِمْتُ عَلَيْهِ ‏ ‏الْمَدِينَةَ ‏ ‏فَدَخَلْتُ عَلَيْهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَتَعْرِفُنِي قَالَ نَعَمْ أَلَسْتَ أَنْتَ الَّذِي أَتَيْتَنِي ‏ ‏بِمَكَّةَ ‏ ‏قَالَ قُلْتُ بَلَى فَقُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي مِمَّا عَلَّمَكَ اللَّهُ وَأَجْهَلُ قَالَ ‏ ‏إِذَا صَلَّيْتَ الصُّبْحَ فَأَقْصِرْ عَنْ الصَّلَاةِ حَتَّى تَطْلُعَ الشَّمْسُ فَإِذَا طَلَعَتْ فَلَا تُصَلِّ حَتَّى تَرْتَفِعَ فَإِنَّهَا تَطْلُعُ حِينَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ فَإِذَا ارْتَفَعَتْ ‏ ‏قِيدَ ‏ ‏رُمْحٍ أَوْ رُمْحَيْنِ فَصَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ حَتَّى ‏ ‏يَسْتَقِلَّ ‏ ‏الرُّمْحُ بِالظِّلِّ ثُمَّ أَقْصِرْ عَنْ الصَّلَاةِ فَإِنَّهَا حِينَئِذٍ ‏ ‏تُسْجَرُ ‏ ‏جَهَنَّمُ فَإِذَا ‏ ‏فَاءَ ‏ ‏الْفَيْءُ ‏ ‏فَصَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ حَتَّى تُصَلِّيَ الْعَصْرَ فَإِذَا صَلَّيْتَ الْعَصْرَ فَأَقْصِرْ عَنْ الصَّلَاةِ حَتَّى تَغْرُبَ الشَّمْسُ فَإِنَّهَا تَغْرُبُ حِينَ تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ قُلْتُ يَا نَبِيَّ اللَّهِ أَخْبِرْنِي عَنْ الْوُضُوءِ قَالَ مَا مِنْكُمْ مِنْ أَحَدٍ يَقْرَبُ وَضُوءَهُ ثُمَّ يَتَمَضْمَضُ ‏ ‏وَيَسْتَنْشِقُ ‏ ‏وَيَنْتَثِرُ ‏ ‏إِلَّا خَرَجَتْ خَطَايَاهُ مِنْ فَمِهِ وَخَيَاشِيمِهِ مَعَ الْمَاءِ حِينَ يَنْتَثِرُ ثُمَّ يَغْسِلُ وَجْهَهُ كَمَا أَمَرَهُ اللَّهُ تَعَالَى إِلَّا خَرَجَتْ خَطَايَا وَجْهِهِ مِنْ أَطْرَافِ لِحْيَتِهِ مِنْ الْمَاءِ ثُمَّ يَغْسِلُ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ إِلَّا خَرَجَتْ خَطَايَا يَدَيْهِ مِنْ أَطْرَافِ ‏ ‏أَنَامِلِهِ ‏ ‏ثُمَّ يَمْسَحُ رَأْسَهُ إِلَّا خَرَجَتْ خَطَايَا رَأْسِهِ مِنْ أَطْرَافِ شَعَرِهِ مَعَ الْمَاءِ ثُمَّ يَغْسِلُ قَدَمَيْهِ إِلَى الْكَعْبَيْنِ كَمَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ إِلَّا خَرَجَتْ خَطَايَا قَدَمَيْهِ مِنْ أَطْرَافِ أَصَابِعِهِ مَعَ الْمَاءِ ثُمَّ يَقُومُ فَيَحْمَدُ اللَّهَ عَزَّ وَجَلَّ ‏ ‏وَيُثْنِي عَلَيْهِ بِالَّذِي هُوَ لَهُ أَهْلٌ ثُمَّ يَرْكَعُ رَكْعَتَيْنِ إِلَّا خَرَجَ مِنْ ذَنْبِهِ كَهَيْئَتِهِ يَوْمَ وَلَدَتْهُ أُمُّهُ ‏ ‏قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏يَا ‏ ‏عَمْرُو بْنَ عَبَسَةَ ‏ ‏انْظُرْ مَا تَقُولُ أَسَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُعْطَى هَذَا الرَّجُلُ كُلَّهُ فِي مَقَامِهِ قَالَ فَقَالَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏لَقَدْ كَبِرَتْ سِنِّي وَرَقَّ عَظْمِي وَاقْتَرَبَ أَجَلِي وَمَا بِي مِنْ حَاجَةٍ أَنْ أَكْذِبَ عَلَى اللَّهِ عَزَّ وَجَلَّ وَعَلَى رَسُولِهِ لَوْ لَمْ أَسْمَعْهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا مَرَّةً أَوْ مَرَّتَيْنِ أَوْ ثَلَاثًا لَقَدْ سَمِعْتُهُ سَبْعَ مَرَّاتٍ ‏ ‏أَوْ أَكْثَرَ مِنْ ذَلِكَ ‏","","",""],[16406,16406,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏سُلَيْمٍ يَعْنِي ابْنَ عَامِرٍ ‏ ‏أَنَّ ‏ ‏شُرَحْبِيلَ بْنَ السِّمْطِ ‏ ‏قَالَ ‏ ‏لِعَمْرِو بْنِ عَبَسَةَ ‏ ‏حَدِّثْنَا حَدِيثًا لَيْسَ فِيهِ تَزَيُّدٌ وَلَا نِسْيَانٌ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُسْلِمَةً كَانَتْ ‏ ‏فِكَاكَهُ ‏ ‏مِنْ النَّارِ عُضْوًا بِعُضْوٍ وَمَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ وَمَنْ رَمَى بِسَهْمٍ فَبَلَغَ فَأَصَابَ أَوْ أَخْطَأَ كَانَ كَمَنْ أَعْتَقَ رَقَبَةً مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏","","",""],[16407,16407,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏أَتَيْنَاهُ فَإِذَا هُوَ جَالِسٌ ‏ ‏يَتَغَلَّ ‏ ‏فِي ‏ ‏جَوْفِ ‏ ‏الْمَسْجِدِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ الْمُسْلِمُ ذَهَبَ الْإِثْمُ مِنْ سَمْعِهِ وَبَصَرِهِ وَيَدَيْهِ وَرِجْلَيْهِ ‏ ‏قَالَ ‏ ‏فَجَاءَ ‏ ‏أَبُو ظَبْيَةَ ‏ ‏وَهُوَ يُحَدِّثُنَا فَقَالَ مَا حَدَّثَكُمْ فَذَكَرْنَا لَهُ الَّذِي حَدَّثَنَا قَالَ فَقَالَ أَجَلْ ‏ ‏سَمِعْتُ ‏ ‏عَمْرَو بْنَ عَبَسَةَ ‏ ‏ذَكَرَهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَزَادَ فِيهِ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ رَجُلٍ يَبِيتُ عَلَى طُهْرٍ ثُمَّ ‏ ‏يَتَعَارَّ ‏ ‏مِنْ اللَّيْلِ فَيَذْكُرُ وَيَسْأَلُ اللَّهَ عَزَّ وَجَلَّ خَيْرًا مِنْ خَيْرِ الدُّنْيَا وَالْآخِرَةِ إِلَّا آتَاهُ اللَّهُ عَزَّ وَجَلَّ إِيَّاهُ ‏","","",""],[16408,16408,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَجِيحٍ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏حَاصَرْنَا مَعَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِصْنَ ‏ ‏الطَّائِفِ ‏ ‏فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ بَلَغَ بِسَهْمٍ فَلَهُ دَرَجَةٌ فِي الْجَنَّةِ قَالَ فَبَلَغْتُ يَوْمَئِذٍ سِتَّةَ عَشَرَ سَهْمًا فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَهُوَ ‏ ‏عِدْلُ ‏ ‏مُحَرَّرٍ ‏ ‏وَمَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ وَأَيُّمَا رَجُلٍ مُسْلِمٍ أَعْتَقَ رَجُلًا مُسْلِمًا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ جَاعِلٌ وَفَاءَ كُلِّ عَظْمٍ مِنْ عِظَامِهِ عَظْمًا مِنْ عِظَامِ مُحَرَّرِهِ مِنْ النَّارِ وَأَيُّمَا امْرَأَةٍ مُسْلِمَةٍ أَعْتَقَتْ امْرَأَةً مُسْلِمَةً فَإِنَّ اللَّهَ عَزَّ وَجَلَّ جَاعِلٌ وَفَاءَ كُلِّ عَظْمٍ مِنْ عِظَامِهَا عَظْمًا مِنْ عِظَامِ مُحَرَّرِهَا مِنْ النَّارِ ‏","","",""],[16409,16409,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَهْرَ بْنَ حَوْشَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو ظَبْيَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا رَجُلٍ مُسْلِمٍ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَبَلَغَ مُخْطِئًا أَوْ مُصِيبًا فَلَهُ مِنْ الْأَجْرِ كَرَقَبَةٍ أَعْتَقَهَا مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏","","",""],[16410,16410,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْأَسْوَدُ بْنُ الْعَلَاءِ ‏ ‏عَنْ ‏ ‏حُوَىٍّ ‏ ‏مَوْلَى ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏أَرْسَلَ إِلَيْهِ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏وَهُوَ أَمِيرُ الْمُؤْمِنِينَ قَالَ كَيْفَ الْحَدِيثُ الَّذِي حَدَّثْتَنِي عَنْ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الصُّنَابِحِيُّ ‏ ‏أَنَّهُ لَقِيَ ‏ ‏عَمْرَو بْنَ عَبَسَةَ ‏ ‏فَقَالَ هَلْ مِنْ حَدِيثٍ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا زِيَادَةَ فِيهِ وَلَا نُقْصَانَ قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً أَعْتَقَ اللَّهُ بِكُلِّ عُضْوٍ مِنْهَا عُضْوًا مِنْهُ مِنْ النَّارِ وَمَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ بَلَغَ أَوْ قَصَّرَ كَانَ عِدْلَ رَقَبَةٍ وَمَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَ لَهُ نُورًا يَوْمَ الْقِيَامَةِ ‏","","",""],[16411,16411,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْفَيْضِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏سُلَيْمَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏كَانَ بَيْنَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَبَيْنَ ‏ ‏الرُّومِ ‏ ‏عَهْدٌ وَكَانَ يَسِيرُ نَحْوَ بِلَادِهِمْ حَتَّى يَنْقَضِيَ الْعَهْدُ ‏ ‏فَيَغْزُوَهُمْ فَجَعَلَ رَجُلٌ عَلَى دَابَّةٍ يَقُولُ وَفَاءٌ لَا غَدْرٌ وَفَاءٌ لَا غَدْرٌ فَإِذَا هُوَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ بَيْنَهُ وَبَيْنَ قَوْمٍ عَهْدٌ فَلَا يَحِلَّ عُقْدَةً وَلَا يَشُدَّهَا حَتَّى يَمْضِيَ ‏ ‏أَمَدُهَا ‏ ‏أَوْ ‏ ‏يَنْبِذَ ‏ ‏إِلَيْهِمْ عَلَى سَوَاءٍ فَرَجَعَ ‏ ‏مُعَاوِيَةُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[16412,16412,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَنْ أَسْلَمَ قَالَ حُرٌّ وَعَبْدٌ ‏ ‏قَالَ فَقُلْتُ ‏ ‏وَهَلْ مِنْ سَاعَةٍ أَقْرَبُ إِلَى اللَّهِ تَعَالَى مِنْ أُخْرَى قَالَ جَوْفُ اللَّيْلِ الْآخِرُ صَلِّ مَا بَدَا لَكَ حَتَّى تُصَلِّيَ الصُّبْحَ ثُمَّ انْهَهُ حَتَّى تَطْلُعَ الشَّمْسُ وَمَا دَامَتْ كَأَنَّهَا ‏ ‏حَجَفَةٌ ‏ ‏حَتَّى تَنْتَشِرَ ثُمَّ صَلِّ مَا بَدَا لَك حَتَّى يَقُومَ الْعَمُودُ عَلَى ظِلِّهِ ثُمَّ انْهَهُ حَتَّى تَزُولَ الشَّمْسُ فَإِنَّ جَهَنَّمَ ‏ ‏تُسْجَرُ ‏ ‏لِنِصْفِ النَّهَارِ ثُمَّ صَلِّ مَا بَدَا لَكَ حَتَّى تُصَلِّيَ الْعَصْرَ ثُمَّ انْهَهُ حَتَّى تَغْرُبَ الشَّمْسُ فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَتَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ فَإِنَّ الْعَبْدَ إِذَا تَوَضَّأَ فَغَسَلَ يَدَيْهِ خَرَّتْ خَطَايَاهُ مِنْ بَيْنِ يَدَيْهِ فَإِذَا غَسَلَ وَجْهَهُ خَرَّتْ خَطَايَاهُ مِنْ وَجْهِهِ فَإِذَا غَسَلَ ذِرَاعَيْهِ وَمَسَحَ بِرَأْسِهِ خَرَّتْ خَطَايَاهُ مِنْ بَيْنِ ذِرَاعَيْهِ وَرَأْسِهِ وَإِذَا غَسَلَ رِجْلَيْهِ خَرَّتْ خَطَايَاهُ مِنْ رِجْلَيْهِ فَإِذَا قَامَ إِلَى الصَّلَاةِ وَكَانَ هُوَ وَقَلْبُهُ وَوَجْهُهُ أَوْ كُلُّهُ نَحْوَ الْوَجْهِ إِلَى اللَّهِ عَزَّ وَجَلَّ انْصَرَفَ كَمَا وَلَدَتْهُ أُمُّهُ قَالَ فَقِيلَ لَهُ أَأَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَوْ لَمْ أَسْمَعْهُ مَرَّةً أَوْ مَرَّتَيْنِ أَوْ عَشْرًا أَوْ عِشْرِينَ مَا حَدَّثْتُ بِهِ ‏","","",""],[16413,16413,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ مَا الْإِسْلَامُ قَالَ ‏ ‏أَنْ يُسْلِمَ قَلْبُكَ لِلَّهِ عَزَّ وَجَلَّ وَأَنْ يَسْلَمَ الْمُسْلِمُونَ مِنْ لِسَانِكَ وَيَدِكَ قَالَ فَأَيُّ الْإِسْلَامِ أَفْضَلُ قَالَ الْإِيمَانُ قَالَ وَمَا الْإِيمَانُ قَالَ تُؤْمِنُ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْبَعْثِ بَعْدَ الْمَوْتِ قَالَ فَأَيُّ الْإِيمَانِ أَفْضَلُ قَالَ الْهِجْرَةُ قَالَ فَمَا الْهِجْرَةُ قَالَ تَهْجُرُ السُّوءَ قَالَ فَأَيُّ الْهِجْرَةِ أَفْضَلُ قَالَ الْجِهَادُ قَالَ وَمَا الْجِهَادُ قَالَ أَنْ تُقَاتِلَ الْكُفَّارَ إِذَا لَقِيتَهُمْ قَالَ فَأَيُّ الْجِهَادِ أَفْضَلُ قَالَ مَنْ ‏ ‏عُقِرَ ‏ ‏جَوَادُهُ ‏ ‏وَأُهْرِيقَ ‏ ‏دَمُهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ عَمَلَانِ هُمَا أَفْضَلُ الْأَعْمَالِ إِلَّا مَنْ عَمِلَ بِمِثْلِهِمَا حَجَّةٌ مَبْرُورَةٌ أَوْ عُمْرَةٌ ‏","","",""],[16414,16414,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَنْ مَعَكَ عَلَى هَذَا الْأَمْرِ قَالَ حُرٌّ وَعَبْدٌ وَمَعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَبِلَالٌ ‏ ‏ثُمَّ قَالَ لَهُ ارْجِعْ إِلَى قَوْمِكَ حَتَّى يُمَكِّنَ اللَّهُ عَزَّ وَجَلَّ لِرَسُولِهِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَمْرُو بْنُ عَبَسَةَ ‏ ‏يَقُولُ ‏ ‏لَقَدْ رَأَيْتُنِي وَإِنِّي ‏ ‏لَرُبُعُ ‏ ‏الْإِسْلَامِ ‏","","",""],[16415,16415,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَعُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ وَنَنْصَرِفُ إِلَى السُّوقِ وَلَوْ رَمَى أَحَدُنَا بِالنَّبْلِ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏رَمَى بِنَبْلٍ ‏ ‏لَأَبْصَرَ مَوَاقِعَهَا ‏","","",""],[16416,16416,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏وَيَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَتَّخِذُوا بُيُوتَكُمْ قُبُورًا صَلُّوا فِيهَا ‏","","",""],[16417,16417,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏ح ‏ ‏وَيَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ خَالِدٍ الْجُهَنِيَّ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏أَنَّ ‏ ‏أَبَا عَمْرَةَ ‏ ‏مَوْلَى ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ خَالِدٍ الْجُهَنِيَّ ‏ ‏يُحَدِّثُ أَنَّ رَجُلًا مِنْ الْمُسْلِمِينَ تُوُفِّيَ ‏ ‏بِخَيْبَرَ ‏ ‏وَأَنَّهُ ذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ صَلُّوا عَلَى صَاحِبِكُمْ قَالَ فَتَغَيَّرَتْ وُجُوهُ الْقَوْمِ لِذَلِكَ فَلَمَّا رَأَى الَّذِي بِهِمْ قَالَ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏غَلَّ ‏ ‏فِي سَبِيلِ اللَّهِ فَفَتَّشْنَا مَتَاعَهُ فَوَجَدْنَا فِيهِ خَرَزًا مِنْ خَرَزِ ‏ ‏الْيَهُودِ ‏ ‏مَا ‏ ‏يُسَاوِي دِرْهَمَيْنِ ‏","","",""],[16418,16418,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَمُحَمَّدٌ ‏ ‏ابْنَا ‏ ‏عُبَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدٌ ‏ ‏لَوْلَا أَنْ يُشَقَّ ‏ ‏عَلَى أُمَّتِي لَأَخَّرْتُ صَلَاةَ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ وَلَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[16419,16419,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَطَّرَ صَائِمًا كُتِبَ لَهُ ‏ ‏مِثْلُ أَجْرِهِ إِلَّا أَنَّهُ لَا يَنْقُصُ مِنْ أَجْرِ الصَّائِمِ شَيْءٌ وَمَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏خَلَفَهُ ‏ ‏فِي أَهْلِهِ كُتِبَ لَهُ مِثْلُ أَجْرِهِ إِلَّا أَنَّهُ لَا يَنْقُصُ مِنْ أَجْرِ الْغَازِي شَيْءٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا إِلَّا أَنَّهُ قَالَ مِنْ غَيْرِ أَنْ لَا يُنْتَقَصُ ‏","","",""],[16420,16420,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏لَعَنَ رَجُلٌ دِيكًا صَاحَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَلْعَنْهُ فَإِنَّهُ يَدْعُو إِلَى الصَّلَاةِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فِي أَثَرِ سَمَاءٍ فَذَكَرَ الْحَدِيثَ ‏","","",""],[16421,16421,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْأَعْمَى ‏ ‏يُخْبِرُ عَنْ ‏ ‏رَجُلٍ يُقَالُ لَهُ ‏ ‏السَّائِبُ ‏ ‏مَوْلَى ‏ ‏الْفَارِسِيِّينَ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏مَوْلًى ‏ ‏لِفَارِسَ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏مَوْلَى ‏ ‏الْفَارِسِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏أَنَّهُ رَآهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَهُوَ خَلِيفَةٌ رَكَعَ بَعْدَ الْعَصْرِ رَكْعَتَيْنِ فَمَشَى إِلَيْهِ فَضَرَبَهُ ‏ ‏بِالدِّرَّةِ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي كَمَا هُوَ فَلَمَّا انْصَرَفَ قَالَ ‏ ‏زَيْدٌ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ فَوَاللَّهِ ‏ ‏لَا أَدَعُهُمَا أَبَدًا بَعْدَ أَنْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهِمَا ‏ ‏قَالَ ‏ ‏فَجَلَسَ إِلَيْهِ ‏ ‏عُمَرُ ‏ ‏وَقَالَ ‏ ‏يَا ‏ ‏زَيْدُ بْنَ خَالِدٍ ‏ ‏لَوْلَا أَنِّي أَخْشَى أَنْ يَتَّخِذَهَا النَّاسُ سُلَّمًا إِلَى الصَّلَاةِ حَتَّى اللَّيْلِ لَمْ أَضْرِبْ فِيهِمَا ‏","","",""],[16422,16422,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ زَيْدٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏ضَالَّةِ رَاعِي الْغَنَمِ قَالَ هِيَ لَكَ أَوْ لِلذِّئْبِ قَالَ يَا رَسُولَ اللَّهِ مَا تَقُولُ فِي ضَالَّةِ رَاعِي الْإِبِلِ قَالَ وَمَا لَكَ وَلَهَا مَعَهَا ‏ ‏سِقَاؤُهَا ‏ ‏وَحِذَاؤُهَا ‏ ‏وَتَأْكُلُ مِنْ أَطْرَافِ الشَّجَرِ قَالَ يَا رَسُولَ اللَّهِ مَا تَقُولُ فِي الْوَرِقِ إِذَا وَجَدْتُهَا قَالَ اعْلَمْ ‏ ‏وِعَاءَهَا ‏ ‏وَوِكَاءَهَا ‏ ‏وَعَدَدَهَا ثُمَّ عَرِّفْهَا سَنَةً فَإِنْ جَاءَ صَاحِبُهَا فَادْفَعْهَا إِلَيْهِ وَإِلَّا فَهِيَ لَكَ أَوْ اسْتَمْتِعْ بِهَا أَوْ نَحْوَ هَذَا ‏","","",""],[16423,16423,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَزَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ ابْنِي كَانَ ‏ ‏عَسِيفًا ‏ ‏عَلَى هَذَا فَزَنَى بِامْرَأَتِهِ فَأَخْبَرُونِي أَنَّ عَلَى ابْنِي ‏ ‏الرَّجْمَ ‏ ‏فَافْتَدَيْتُ مِنْهُ ‏ ‏بِوَلِيدَةٍ ‏ ‏وَبِمِائَةِ شَاةٍ ثُمَّ أَخْبَرَنِي أَهْلُ الْعِلْمِ أَنَّ عَلَى ابْنِي جَلْدَ مِائَةٍ ‏ ‏وَتَغْرِيبَ ‏ ‏عَامٍ وَأَنَّ عَلَى امْرَأَةِ هَذَا ‏ ‏الرَّجْمَ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ فَاقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللَّهِ أَمَّا الْغَنَمُ ‏ ‏وَالْوَلِيدَةُ ‏ ‏فَرَدٌّ عَلَيْكَ وَأَمَّا ابْنُكَ فَعَلَيْهِ جَلْدُ مِائَةٍ ‏ ‏وَتَغْرِيبُ ‏ ‏عَامٍ ثُمَّ قَالَ لِرَجُلٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏يُقَالُ لَهُ ‏ ‏أُنَيْسٌ ‏ ‏قُمْ يَا ‏ ‏أُنَيْسُ ‏ ‏فَاسْأَلْ امْرَأَةَ هَذَا فَإِنْ اعْتَرَفَتْ ‏ ‏فَارْجُمْهَا ‏","","",""],[16424,16424,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَقَدْ غَزَا وَمَنْ ‏ ‏خَلَفَهُ ‏ ‏فَقَدْ غَزَا ‏","","",""],[16425,16425,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏إِنْ شَاءَ اللَّهُ قَالَ ‏ ‏إِسْحَاقُ ‏ ‏قَالَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ الشُّهَدَاءِ الَّذِي يَأْتِي بِالشَّهَادَةِ قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[16426,16426,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ ثُمَّ أَخْرُجُ إِلَى السُّوقِ فَلَوْ أَرْمِي لَأَبْصَرْتُ مَوَاقِعَ ‏ ‏نَبْلِي ‏","","",""],[16427,16427,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَزَيْدَ بْنَ خَالِدٍ الْجُهَنِيَّ ‏ ‏وَشَبْلًا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ بَعْضُ النَّاسِ ‏ ‏ابْنَ مَعْبَدٍ ‏ ‏وَالَّذِي حَفِظْتُ ‏ ‏شِبْلًا ‏ ‏قَالُوا ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ رَجُلٌ فَقَالَ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ إِلَّا قَضَيْتَ بَيْنَنَا بِكِتَابِ اللَّهِ فَقَامَ خَصْمُهُ وَكَانَ أَفْقَهَ مِنْهُ فَقَالَ صَدَقَ اقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ وَأْذَنْ لِي فَأَتَكَلَّمَ قَالَ قُلْ قَالَ إِنَّ ابْنِي كَانَ ‏ ‏عَسِيفًا ‏ ‏عَلَى هَذَا وَإِنَّهُ زَنَى بِامْرَأَتِهِ فَافْتَدَيْتُ مِنْهُ بِمِائَةِ شَاةٍ وَخَادِمٍ ثُمَّ سَأَلْتُ رِجَالًا مِنْ أَهْلِ الْعِلْمِ فَأَخْبَرُونِي أَنَّ عَلَى ابْنِي جَلْدَ مِائَةٍ ‏ ‏وَتَغْرِيبَ ‏ ‏عَامٍ وَعَلَى امْرَأَةِ هَذَا ‏ ‏الرَّجْمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ الْمِائَةُ شَاةٍ وَالْخَادِمُ رَدٌّ عَلَيْكَ وَعَلَى ابْنِكَ جَلْدُ مِائَةٍ ‏ ‏وَتَغْرِيبُ ‏ ‏عَامٍ ‏ ‏وَاغْدُ ‏ ‏يَا ‏ ‏أُنَيْسُ ‏ ‏رَجُلٌ مِنْ ‏ ‏أَسْلَمَ ‏ ‏عَلَى امْرَأَةِ هَذَا فَإِنْ اعْتَرَفَتْ ‏ ‏فَارْجُمْهَا ‏ ‏فَغَدَا ‏ ‏عَلَيْهَا فَاعْتَرَفَتْ ‏ ‏فَرَجَمَهَا ‏","","",""],[16428,16428,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَزَيْدِ بْنِ خَالِدٍ ‏ ‏وَشَبْلٍ ‏ ‏قَالُوا ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْأَمَةِ تَزْنِي قَبْلَ أَنْ ‏ ‏تُحْصَنَ ‏ ‏قَالَ ‏ ‏اجْلِدُوهَا فَإِنْ عَادَتْ فَاجْلِدُوهَا فَإِنْ عَادَتْ فَاجْلِدُوهَا فَإِنْ عَادَتْ فَبِيعُوهَا وَلَوْ ‏ ‏بِضَفِيرٍ ‏","","",""],[16429,16429,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتَّخِذُوا بُيُوتَكُمْ قُبُورًا صَلُّوا فِيهَا وَمَنْ فَطَّرَ صَائِمًا كُتِبَ لَهُ مِثْلُ أَجْرِ الصَّائِمِ لَا يَنْقُصُ مِنْ أَجْرِ الصَّائِمِ شَيْءٌ وَمَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏خَلَفَهُ ‏ ‏فِي أَهْلِهِ كُتِبَ لَهُ مِثْلُ أَجْرِ الْغَازِي فِي أَنَّهُ لَا يَنْقُصُ مِنْ أَجْرِ الْغَازِي شَيْءٌ ‏","","",""],[16430,16430,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللَّهِ فَقَدْ غَزَا وَمَنْ خَلَفَ غَازِيًا فِي أَهْلِهِ بِخَيْرٍ فَقَدْ غَزَا ‏","","",""],[16431,16431,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏اللُّقَطَةِ ‏ ‏فَقَالَ ‏ ‏عَرِّفْهَا ‏ ‏سَنَةً فَإِنْ ‏ ‏اعْتُرِفَتْ ‏ ‏فَأَدِّهَا وَإِلَّا فَاعْرِفْ ‏ ‏عِفَاصَهَا ‏ ‏وَوِكَاءَهَا ‏ ‏وَعَدَدَهَا وَإِلَّا فَكُلْهَا فَإِنْ اعْتُرِفَتْ فَأَدِّهَا ‏","","",""],[16432,16432,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ الشَّهَادَةِ الَّذِينَ يَبْدَءُونَ بِشَهَادَتِهِمْ مِنْ غَيْرِ أَنْ يُسْأَلُوا عَنْهَا ‏","","",""],[16433,16433,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْبٌ يَعْنِي ابْنَ شَدَّادٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏زَيْدُ بْنُ خَالِدٍ ‏ ‏يَضَعُ السِّوَاكَ مِنْهُ مَوْضِعَ الْقَلَمِ مِنْ أُذُنِ الْكَاتِبِ كُلَّمَا قَامَ إِلَى الصَّلَاةِ ‏ ‏اسْتَاكَ ‏","","",""],[16434,16434,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏مُطِرَ ‏ ‏النَّاسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَلَمَّا أَصْبَحُوا قَالَ أَلَمْ تَسْمَعُوا مَا قَالَ رَبُّكُمْ عَزَّ وَجَلَّ اللَّيْلَةَ قَالَ ‏ ‏مَا أَنْعَمْتُ عَلَى عِبَادِي نِعْمَةً إِلَّا أَصْبَحَ بِهَا قَوْمٌ كَافِرِينَ بِالَّذِي آمَنَ بِي ‏","","",""],[16435,16435,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏مَوْلَى ‏ ‏الْمُنْبَعِثِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنِي ‏ ‏رَبِيعَةُ ‏ ‏أَنَّهُ قَالَ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏فَسَأَلْتُ ‏ ‏رَبِيعَةَ ‏ ‏فَقَالَ أَخْبَرَنِيهِ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ضَالَّةِ الْإِبِلِ فَغَضِبَ وَاحْمَرَّتْ ‏ ‏وَجْنَتَاهُ ‏ ‏وَقَالَ ‏ ‏مَا لَكَ وَلَهَا مَعَهَا ‏ ‏الْحِذَاءُ ‏ ‏وَالسِّقَاءُ ‏ ‏تَرِدُ الْمَاءَ وَتَأْكُلُ الشَّجَرَ حَتَّى تَجِيءَ رَبَّهَا وَسُئِلَ عَنْ ضَالَّةِ الْغَنَمِ فَقَالَ خُذْهَا فَإِنَّمَا هِيَ لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ وَسُئِلَ عَنْ ‏ ‏اللُّقَطَةِ ‏ ‏فَقَالَ اعْرِفْ ‏ ‏عِفَاصَهَا ‏ ‏وَوِكَاءَهَا ‏ ‏ثُمَّ ‏ ‏عَرِّفْهَا ‏ ‏سَنَةً فَإِنْ ‏ ‏اعْتُرِفَتْ ‏ ‏وَإِلَّا فَاخْلِطْهَا بِمَالِكَ ‏","","",""],[16436,16436,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي ‏ ‏أَبُو جُهَيْمٍ ‏ ‏ابْنُ أُخْتِ ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏إِلَى ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏أَسْأَلُهُ مَا سَمِعَ فِي الْمَارِّ بَيْنَ يَدَيْ الْمُصَلِّي قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَأَنْ يَقُومَ أَرْبَعِينَ لَا أَدْرِي مِنْ يَوْمٍ أَوْ شَهْرٍ أَوْ سَنَةٍ خَيْرٌ لَهُ مِنْ أَنْ يَمُرَّ بَيْنَ يَدَيْهِ ‏","","",""],[16437,16437,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَوْلَى الْجُهَيْنَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النُّهْبَةِ ‏ ‏وَالْخُلْسَةِ ‏","","",""],[16438,16438,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ ثُمَّ نَنْصَرِفُ إِلَى السُّوقِ وَلَوْ رُمِيَ بِنَبْلٍ لَأَبْصَرْتُ مَوَاقِعَهَا ‏","","",""],[16439,16439,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ يَعْنِي ابْنَ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ وُضُوءَهُ ثُمَّ صَلَّى رَكْعَتَيْنِ لَا ‏ ‏يَسْهُو فِيهِمَا غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[16440,16440,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ ‏ ‏و حَدَّثَنَا ‏ ‏سُرَيْجٌ هُوَ ابْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَالِمٍ الْجَيْشَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏آوَى ‏ ‏ضَالَّةً ‏ ‏فَهُوَ ضَالٌّ مَا لَمْ يُعَرِّفْهَا ‏","","",""],[16441,16441,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُبَارَكٍ الْهُنَائِيُّ ‏ ‏بَصْرِيٌّ ثِقَةٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَهَّزَ غَازِيًا فَقَدْ غَزَا وَمَنْ ‏ ‏خَلَفَهُ ‏ ‏فِي أَهْلِهِ فَقَدْ غَزَا ‏","","",""],[16442,16442,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الْأَمَةِ تَزْنِي وَلَمْ ‏ ‏تُحْصَنْ ‏ ‏قَالَ ‏ ‏اجْلِدْهَا فَإِنْ زَنَتْ فَاجْلِدْهَا فَقَالَ فِي الثَّالِثَةِ ‏ ‏أَوْ فِي الرَّابِعَةِ ‏ ‏فَإِنْ زَنَتْ فَبِعْهَا وَلَوْ ‏ ‏بِضَفِيرٍ ‏ ‏وَالضَّفِيرُ الْحَبْلُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏الْمَعْنَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏قَالَا ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْأَمَةِ فَذَكَرَ الْحَدِيثَ وَقَالَ فِي الثَّالِثَةِ ‏ ‏أَوْ الرَّابِعَةِ ‏ ‏الزُّهْرِيُّ ‏ ‏شَكَّ ‏","","",""],[16443,16443,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ ‏ ‏مَوْلَى ‏ ‏الْمُنْبَعِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلُقَطَةٍ ‏ ‏فَقَالَ ‏ ‏عَرِّفْهَا ‏ ‏سَنَةً ثُمَّ اعْرِفْ ‏ ‏عِفَاصَهَا ‏ ‏وَوِكَاءَهَا ‏ ‏فَإِنْ جَاءَ أَحَدٌ يُخْبِرُكَ بِهَا وَإِلَّا ‏ ‏فَاسْتَنْفِقْهَا ‏ ‏قَالَ يَا رَسُولَ اللَّهِ ‏ ‏فَضَالَّةُ ‏ ‏الْغَنَمِ قَالَ لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏ضَالَّةُ ‏ ‏الْإِبِلِ قَالَ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ مَا لَكَ وَلَهَا مَعَهَا ‏ ‏حِذَاؤُهَا ‏ ‏وَسِقَاؤُهَا ‏ ‏تَرِدُ الْمَاءَ وَتَأْكُلُ الشَّجَرَ ‏","","",""],[16444,16444,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الصُّبْحِ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏عَلَى أَثَرِ سَمَاءٍ كَانَتْ مِنْ اللَّيْلِ فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَى النَّاسِ قَالَ هَلْ تَدْرُونَ مَاذَا قَالَ رَبُّكُمْ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏كَافِرٌ بِالْكَوْكَبِ وَمُؤْمِنٌ بِالْكَوْكَبِ كَافِرٌ بِي ‏ ‏فَأَمَّا مَنْ قَالَ مُطِرْنَا بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَذَلِكَ مُؤْمِنٌ بِي كَافِرٌ بِالْكَوْكَبِ وَأَمَّا مَنْ قَالَ مُطِرْنَا ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَكَذَا فَذَلِكَ كَافِرٌ بِي مُؤْمِنٌ بِالْكَوْكَبِ ‏","","",""],[16445,16445,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي بَكْرِ بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ الشَّهَادَةِ مَنْ شَهِدَ بِهَا صَاحِبُهَا قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[16446,16446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏إِسْمَاعِيلُ بْنُ رَجَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَوْسَ بْنَ ضَمْعَجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مَسْعُودٍ الْأَنْصَارِيَّ الْبَدْرِيَّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ تَعَالَى وَأَقْدَمُهُمْ قِرَاءَةً فَإِنْ كَانَتْ قِرَاءَتُهُمْ سَوَاءً فَلْيَؤُمَّهُمْ أَقْدَمُهُمْ هِجْرَةً فَإِنْ كَانَ هِجْرَتُهُمْ سَوَاءً فَلْيَؤُمَّهُمْ أَكْبَرُهُمْ سِنًّا وَلَا يُؤَمُّ الرَّجُلُ فِي أَهْلِهِ وَلَا فِي سُلْطَانِهِ وَلَا يُجْلَسُ عَلَى ‏ ‏تَكْرِمَتِهِ ‏ ‏فِي بَيْتِهِ إِلَّا أَنْ يَأْذَنَ لَكَ أَوْ إِلَّا بِإِذْنِهِ ‏","","",""],[16447,16447,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ رَجُلًا أَتَى اللَّهُ بِهِ عَزَّ وَجَلَّ فَقَالَ ‏ ‏مَاذَا عَمِلْتَ فِي الدُّنْيَا فَقَالَ لَهُ الرَّجُلُ مَا عَمِلْتُ مِنْ مِثْقَالِ ذَرَّةٍ مِنْ خَيْرٍ ‏ ‏أَرْجُوكَ بِهَا فَقَالَهَا لَهُ ثَلَاثًا وَقَالَ فِي الثَّالِثَةِ أَيْ رَبِّ كُنْتَ أَعْطَيْتَنِي فَضْلًا مِنْ مَالٍ فِي الدُّنْيَا فَكُنْتُ أُبَايِعُ النَّاسَ وَكَانَ مِنْ خُلُقِي ‏ ‏أَتَجَاوُزُ ‏ ‏عَنْهُ وَكُنْتُ أُيَسِّرُ عَلَى الْمُوسِرِ ‏ ‏وَأُنْظِرُ ‏ ‏الْمُعْسِرَ فَقَالَ عَزَّ وَجَلَّ نَحْنُ أَوْلَى بِذَلِكَ مِنْكَ ‏ ‏تَجَاوَزُوا ‏ ‏عَنْ عَبْدِي فَغُفِرَ لَهُ فَقَالَ ‏ ‏أَبُو مَسْعُودٍ ‏ ‏هَكَذَا سَمِعْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَجُلٌ آخَرُ ‏ ‏أَمَرَ أَهْلَهُ إِذَا مَاتَ أَنْ يُحَرِّقُوهُ ثُمَّ يَطْحَنُوهُ ثُمَّ ‏ ‏يُذَرُّونَهُ ‏ ‏فِي يَوْمِ رِيحٍ عَاصِفٍ فَفَعَلُوا ذَلِكَ بِهِ فَجُمِعَ إِلَى رَبِّهِ عَزَّ وَجَلَّ فَقَالَ لَهُ مَا حَمَلَكَ عَلَى هَذَا قَالَ يَا رَبِّ لَمْ يَكُنْ عَبْدٌ أَعْصَى لَكَ مِنِّي فَرَجَوْتُ أَنْ أَنْجُوَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏تَجَاوَزُوا ‏ ‏عَنْ عَبْدِي فَغُفِرَ لَهُ قَالَ ‏ ‏أَبُو مَسْعُودٍ ‏ ‏هَكَذَا سَمِعْتُهُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16448,16448,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ وَاللَّهِ إِنِّي لَأَتَأَخَّرُ فِي صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏مَخَافَةَ فُلَانٍ ‏ ‏يَعْنِي إِمَامَهُمْ ‏ ‏قَالَ فَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ غَضَبًا فِي مَوْعِظَةٍ مِنْهُ يَوْمَئِذٍ فَقَالَ أَيُّهَا النَّاسُ ‏ ‏إِنَّ مِنْكُمْ مُنَفِّرِينَ فَأَيُّكُمْ مَا صَلَّى بِالنَّاسِ فَلْيُخَفِّفْ فَإِنَّ فِيهِمْ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ‏","","",""],[16449,16449,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَشَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ نَحْوَ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ ‏ ‏الْإِيمَانُ هَاهُنَا قَالَ أَلَا وَإِنَّ الْقَسْوَةَ وَغِلَظَ الْقُلُوبِ فِي ‏ ‏الْفَدَّادِينَ ‏ ‏أَصْحَابِ الْإِبِلِ حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ فِي ‏ ‏رَبِيعَةَ ‏ ‏وَمُضَرَ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏عِنْدَ أُصُولِ ‏ ‏أَذْنَابِ ‏ ‏الْإِبِلِ ‏","","",""],[16450,16450,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ الْمُجْمِرِ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ كَيْفَ نُصَلِّي عَلَيْكَ فَقَالَ ‏ ‏قُولُوا اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ ‏ ‏وَقَرَأْتُ هَذَا الْحَدِيثَ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏","","",""],[16451,16451,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَرَأَ الْآيَتَيْنِ مِنْ آخِرِ ‏ ‏الْبَقَرَةِ ‏ ‏فِي لَيْلَةٍ ‏ ‏كَفَتَاهُ ‏","","",""],[16452,16452,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ يَعْنِي ابْنَ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْقَاسِمِ ‏ ‏أَوْ ‏ ‏الْقَاسِمِ بْنِ عُبَيْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ هَذَا الْأَمْرَ فِيكُمْ وَإِنَّكُمْ وُلَاتُهُ وَلَنْ يَزَالَ فِيكُمْ حَتَّى تُحْدِثُوا أَعْمَالًا فَإِذَا فَعَلْتُمْ ذَلِكَ بَعَثَ اللَّهُ عَزَّ وَجَلَّ عَلَيْكُمْ شَرَّ خَلْقِهِ ‏ ‏فَيَلْتَحِيكُمْ ‏ ‏كَمَا ‏ ‏يُلْتَحَى ‏ ‏الْقَضِيبُ ‏","","",""],[16453,16453,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا مَسْعُودٍ عُقْبَةَ بْنَ عَمْرٍو ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ثَمَنِ الْكَلْبِ وَمَهْرِ الْبَغِيِّ ‏ ‏وَحُلْوَانِ ‏ ‏الْكَاهِنِ ‏","","",""],[16454,16454,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ الدَّسْتُوَائِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ ‏ ‏أَوَّلَ اللَّيْلِ وَأَوْسَطَهُ وَآخِرَهُ ‏","","",""],[16455,16455,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏فِي الصَّلَاةِ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا الْمَرْءُ الْمُسْلِمُ صَلَّى عَلَيْهِ فِي صَلَاتِهِ ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَبْدِ رَبِّهِ الْأَنْصَارِيِّ ‏ ‏أَخِي ‏ ‏بَلْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَقْبَلَ رَجُلٌ حَتَّى جَلَسَ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ عِنْدَهُ فَقَالَ يَا رَسُولَ اللَّهِ أَمَّا السَّلَامُ عَلَيْكَ فَقَدْ عَرَفْنَاهُ فَكَيْفَ نُصَلِّي عَلَيْكَ إِذَا نَحْنُ صَلَّيْنَا فِي صَلَاتِنَا صَلَّى اللَّهُ عَلَيْكَ قَالَ فَصَمَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَحْبَبْنَا أَنَّ الرَّجُلَ لَمْ يَسْأَلْهُ فَقَالَ إِذَا أَنْتُمْ صَلَّيْتُمْ عَلَيَّ فَقُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏النَّبِيِّ الْأُمِّيِّ وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَآلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏النَّبِيِّ الْأُمِّيِّ كَمَا بَارَكْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَعَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ ‏","","",""],[16456,16456,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ التَّيْمِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَعْمَرٍ الْأَزْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُجْزِئُ صَلَاةٌ لِرَجُلٍ أَوْ لِأَحَدٍ لَا ‏ ‏يُقِيمُ ‏ ‏ظَهْرَهُ فِي الرُّكُوعِ وَالسُّجُودِ ‏","","",""],[16457,16457,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏إِنَّ ‏ ‏أَبَا بَكْرِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامِ بْنِ الْمُغِيرَةِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا مَسْعُودٍ الْأَنْصَارِيَّ ‏ ‏صَاحِبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَا ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏وَهُوَ جَدُّ ‏ ‏زَيْدِ بْنِ الْحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏أَبُو أُمِّهِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَاهُمْ عَنْ ثَمَنِ الْكَلْبِ وَمَهْرِ ‏ ‏الْبَغِيِّ ‏ ‏وَحُلْوَانِ ‏ ‏الْكَاهِنِ ‏","","",""],[16458,16458,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ وَهُوَ ابْنُ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قِيلَ لَهُ مَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي زَعَمُوا قَالَ ‏ ‏بِئْسَ ‏ ‏مَطِيَّةُ ‏ ‏الرَّجُلِ ‏","","",""],[16459,16459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَالِمٌ الْبَرَّادُ ‏ ‏قَالَ ‏ ‏وَكَانَ عِنْدِي أَوْثَقَ مِنْ نَفْسِي ‏ ‏قَالَ ‏ ‏قَالَ لَنَا ‏ ‏أَبُو مَسْعُودٍ الْبَدْرِيُّ ‏ ‏أَلَا أُصَلِّي لَكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَكَبَّرَ فَرَكَعَ فَوَضَعَ كَفَّيْهِ عَلَى رُكْبَتَيْهِ وَفُصِلَتْ أَصَابِعُهُ عَلَى سَاقَيْهِ ‏ ‏وَجَافَى ‏ ‏عَنْ إِبْطَيْهِ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ‏ ‏فَاسْتَوَى ‏ ‏قَائِمًا حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ كَبَّرَ وَسَجَدَ ‏ ‏وَجَافَى ‏ ‏عَنْ إِبْطَيْهِ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ رَفَعَ رَأْسَهُ ‏ ‏فَاسْتَوَى ‏ ‏جَالِسًا حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ سَجَدَ الثَّانِيَةَ فَصَلَّى بِنَا أَرْبَعَ رَكَعَاتٍ هَكَذَا ثُمَّ قَالَ هَكَذَا كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى ‏","","",""],[16460,16460,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏قَيْسَ بْنَ أَبِي حَازِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ فُلَانًا يُطِيلُ بِنَا الصَّلَاةَ حَتَّى إِنِّي لَأَتَأَخَّرُ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَضَبًا مَا رَأَيْتُهُ غَضِبَ فِي مَوْعِظَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِيكُمْ مُنَفِّرِينَ فَمَنْ أَمَّ قَوْمًا فَلْيُخَفِّفْ بِهِمْ الصَّلَاةَ فَإِنَّ وَرَاءَهُ الْكَبِيرَ وَالْمَرِيضَ وَذَا ‏ ‏الْحَاجَةِ ‏","","",""],[16461,16461,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏انْطَلَقَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ ‏ ‏الْعَبَّاسُ ‏ ‏عَمُّهُ إِلَى السَّبْعِينَ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عِنْدَ ‏ ‏الْعَقَبَةِ ‏ ‏تَحْتَ الشَّجَرَةِ فَقَالَ لِيَتَكَلَّمْ مُتَكَلِّمُكُمْ وَلَا يُطِيلُ الْخُطْبَةَ فَإِنَّ عَلَيْكُمْ مِنْ الْمُشْرِكِينَ عَيْنًا وَإِنْ يَعْلَمُوا بِكُمْ يَفْضَحُوكُمْ فَقَالَ قَائِلُهُمْ وَهُوَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏سَلْ يَا ‏ ‏مُحَمَّدُ ‏ ‏لِرَبِّكَ مَا شِئْتَ ثُمَّ سَلْ لِنَفْسِكَ وَلِأَصْحَابِكَ مَا شِئْتَ ثُمَّ أَخْبِرْنَا مَا لَنَا ‏ ‏مِنْ الثَّوَابِ عَلَى اللَّهِ عَزَّ وَجَلَّ وَعَلَيْكُمْ إِذَا فَعَلْنَا ذَلِكَ قَالَ فَقَالَ ‏ ‏أَسْأَلُكُمْ لِرَبِّي عَزَّ وَجَلَّ أَنْ تَعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَأَسْأَلُكُمْ لِنَفْسِي وَلِأَصْحَابِي أَنْ تُؤْوُونَا وَتَنْصُرُونَا وَتَمْنَعُونَا مِمَّا مَنَعْتُمْ مِنْهُ أَنْفُسَكُمْ قَالُوا فَمَا لَنَا إِذَا فَعَلْنَا ذَلِكَ قَالَ لَكُمْ الْجَنَّةُ قَالُوا فَلَكَ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏نَحْوَ هَذَا ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏أَبُو مَسْعُودٍ ‏ ‏أَصْغَرَهُمْ سِنًّا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يَقُولُ ‏ ‏مَا سَمِعَ الشِّيبُ وَلَا الشُّبَّانُ خُطْبَةً مِثْلَهَا ‏","","",""],[16462,16462,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُقْبَةُ بْنُ عَمْرٍو ‏ ‏أَلَا ‏ ‏أُرِيكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَقَامَ وَكَبَّرَ ثُمَّ رَكَعَ ‏ ‏وَجَافَى ‏ ‏يَدَيْهِ وَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ وَفَرَّجَ بَيْنَ أَصَابِعِهِ مِنْ وَرَاءِ رُكْبَتَيْهِ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ سَجَدَ ‏ ‏فَجَافَى ‏ ‏حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ قَالَ فَصَلَّى أَرْبَعَ رَكَعَاتٍ ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏ ‏أَوْ هَكَذَا كَانَ ‏ ‏يُصَلِّي بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16463,16463,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قُلْتُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا أَنْفَقَ عَلَى أَهْلِهِ نَفَقَةً وَهُوَ ‏ ‏يَحْتَسِبُهَا ‏ ‏كَانَتْ لَهُ ‏ ‏صَدَقَةً ‏","","",""],[16464,16464,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُوسِبَ رَجُلٌ مِمَّنْ كَانَ قَبْلَكُمْ فَلَمْ يُوجَدْ لَهُ مِنْ الْخَيْرِ شَيْءٌ إِلَّا أَنَّهُ كَانَ رَجُلًا مُوسِرًا وَكَانَ يُخَالِطُ النَّاسَ فَكَانَ يَقُولُ لِغِلْمَانِهِ ‏ ‏تَجَاوَزُوا ‏ ‏عَنْ الْمُعْسِرِ قَالَ فَقَالَ اللَّهُ عَزَّ وَجَلَّ لِمَلَائِكَتِهِ ‏ ‏نَحْنُ أَحَقُّ بِذَلِكَ مِنْهُ ‏ ‏تَجَاوَزُوا ‏ ‏عَنْهُ ‏","","",""],[16465,16465,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏وَمُحَمَّدٌ ‏ ‏يَعْنِي ابْنَيْ ‏ ‏عُبَيْدٍ ‏ ‏قَالُوا أَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ إِنِّي أُبْدِعَ بِي فَاحْمِلْنِي قَالَ مَا عِنْدِي مَا أَحْمِلُكَ عَلَيْهِ وَلَكِنْ ائْتِ فُلَانًا فَأَتَاهُ فَحَمَلَهُ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فَإِنَّهُ قَدْ بُدِعَ بِي ‏","","",""],[16466,16466,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُكَنَّى ‏ ‏أَبَا شُعَيْبٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَرَفْتُ فِي وَجْهِهِ الْجُوعَ فَأَتَيْتُ غُلَامًا لِي قَصَّابًا فَأَمَرْتُهُ أَنْ يَجْعَلَ لَنَا طَعَامًا لِخَمْسَةِ رِجَالٍ قَالَ ثُمَّ دَعَوْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَامِسَ خَمْسَةٍ وَتَبِعَهُمْ رَجُلٌ فَلَمَّا ‏ ‏بَلَغَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَابَ قَالَ ‏ ‏هَذَا قَدْ تَبِعَنَا إِنْ شِئْتَ أَنْ تَأْذَنَ لَهُ وَإِلَّا رَجَعَ فَأَذِنَ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي أُبْدِعَ بِي أَيْ انْقَطَعَ بِي فَاحْمِلْنِي فَذَكَرَ الْحَدِيثَ ‏","","",""],[16467,16467,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا أَضْرِبُ غُلَامًا لِي إِذْ سَمِعْتُ صَوْتًا مِنْ وَرَائِي اعْلَمْ ‏ ‏أَبَا مَسْعُودٍ ‏ ‏ثَلَاثًا فَالْتَفَتُّ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏وَاللَّهِ لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَى هَذَا قَالَ فَحَلَفْتُ أَنْ لَا أَضْرِبَ مَمْلُوكًا أَبَدًا ‏","","",""],[16468,16468,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ثَمَنِ الْكَلْبِ وَعَنْ مَهْرِ ‏ ‏الْبَغِيِّ ‏ ‏وَعَنْ ‏ ‏حُلْوَانِ ‏ ‏الْكَاهِنِ ‏","","",""],[16469,16469,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فَأَخَّرَ صَلَاةَ الْعَصْرِ مَرَّةً فَقَالَ لَهُ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏حَدَّثَنِي ‏ ‏بَشِيرُ بْنُ أَبِي مَسْعُودٍ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخَّرَ الصَّلَاةَ مَرَّةً ‏ ‏يَعْنِي الْعَصْرَ ‏ ‏فَقَالَ لَهُ ‏ ‏أَبُو مَسْعُودٍ ‏ ‏أَمَا وَاللَّهِ يَا ‏ ‏مُغِيرَةُ ‏ ‏لَقَدْ عَلِمْتُ أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏نَزَلَ فَصَلَّى وَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَلَّى النَّاسُ مَعَهُ ثُمَّ نَزَلَ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَلَّى النَّاسُ مَعَهُ حَتَّى عَدَّ خَمْسَ صَلَوَاتٍ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏انْظُرْ مَا تَقُولُ يَا ‏ ‏عُرْوَةُ ‏ ‏أَوَإِنَّ ‏ ‏جِبْرِيلَ ‏ ‏هُوَ ‏ ‏سَنَّ ‏ ‏الصَّلَاةَ قَالَ ‏ ‏عُرْوَةُ ‏ ‏كَذَلِكَ حَدَّثَنِي ‏ ‏بَشِيرُ بْنُ أَبِي مَسْعُودٍ ‏ ‏فَمَا زَالَ ‏ ‏عُمَرُ ‏ ‏يَتَعَلَّمُ وَقْتَ الصَّلَاةِ بِعَلَامَةٍ حَتَّى فَارَقَ الدُّنْيَا ‏","","",""],[16470,16470,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رِبْعِيَّ بْنَ حِرَاشٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى إِذَا لَمْ تَسْتَحْيِ فَاصْنَعْ مَا شِئْتَ ‏","","",""],[16471,16471,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏كُنْتُ أُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏حَدِيثًا فَلَقِيتُهُ وَهُوَ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏فَسَأَلْتُهُ فَحَدَّثَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَرَأَ الْآيَتَيْنِ الْآخِرَتَيْنِ مِنْ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏فِي لَيْلَةٍ ‏ ‏كَفَتَاهُ ‏","","",""],[16472,16472,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَوْسَ بْنَ ضَمْعَجٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ تَعَالَى وَأَقْدَمُهُمْ قِرَاءَةً فَإِنْ كَانَتْ قِرَاءَتُهُمْ سَوَاءً فَلْيَؤُمَّهُمْ أَقْدَمُهُمْ هِجْرَةً فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً فَلْيَؤُمَّهُمْ أَكْبَرُهُمْ سِنًّا وَلَا يُؤَمَّنَّ الرَّجُلُ فِي أَهْلِهِ وَلَا فِي سُلْطَانِهِ وَلَا يُجْلَسُ عَلَى ‏ ‏تَكْرِمَتِهِ فِي بَيْتِهِ إِلَّا أَنْ يَأْذَنَ لَهُ أَوْ بِإِذْنِهِ ‏","","",""],[16473,16473,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا مِنْ قَوْمِهِ يُقَالُ لَهُ ‏ ‏أَبُو شُعَيْبٍ ‏ ‏صَنَعَ طَعَامًا فَأَرْسَلَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْتِنِي أَنْتَ وَخَمْسَةٌ مَعَكَ قَالَ فَبَعَثَ إِلَيْهِ أَنْ ائْذَنْ لِي فِي السَّادِسِ ‏","","",""],[16474,16474,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا تَصَدَّقَ بِنَاقَةٍ ‏ ‏مَخْطُومَةٍ ‏ ‏فِي سَبِيلِ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَأْتِيَنَّ يَوْمَ الْقِيَامَةِ بِسَبْعِ مِائَةِ نَاقَةٍ ‏ ‏مَخْطُومَةٍ ‏","","",""],[16475,16475,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَرَأَ الْآيَتَيْنِ مِنْ ‏ ‏الْبَقَرَةِ ‏ ‏فِي لَيْلَةٍ ‏ ‏كَفَتَاهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا مَسْعُودٍ ‏ ‏فَحَدَّثَنِي بِهِ ‏","","",""],[16476,16476,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَرَأَ الْآيَتَيْنِ مِنْ آخِرِ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏فِي لَيْلَةٍ ‏ ‏كَفَتَاهُ ‏","","",""],[16477,16477,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ ضَمْعَجٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَؤُمَّ ‏ ‏الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ تَعَالَى فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَأَعْلَمُهُمْ بِالسُّنَّةِ فَإِنْ كَانُوا فِي السُّنَّةِ سَوَاءً فَأَقْدَمُهُمْ هِجْرَةً فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً فَأَكْبَرُهُمْ سِنًّا وَلَا يُؤَمَّنَّ رَجُلٌ فِي سُلْطَانِهِ وَلَا يُجْلَسْ عَلَى ‏ ‏تَكْرِمَتِهِ ‏ ‏إِلَّا أَنْ يَأْذَنَ ‏","","",""],[16478,16478,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَالثَّوْرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مَسْعُودٍ عُقْبَةَ بْنَ عَمْرٍو الْبَدْرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِمَّا ‏ ‏أَدْرَكَ ‏ ‏النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى إِذَا لَمْ تَسْتَحْيِ فَاصْنَعْ مَا شِئْتَ ‏","","",""],[16479,16479,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ رَجَاءٍ ‏ ‏وَإِسْمَاعِيلُ يَعْنِي ابْنَ عُلَيَّةَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ ضَمْعَجٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ وَأَقْدَمُهُمْ قِرَاءَةً فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَأَقْدَمُهُمْ هِجْرَةً فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً فَأَكْبَرُهُمْ سِنًّا وَلَا يُؤَمَّنَّ الرَّجُلُ فِي سُلْطَانِهِ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏وَلَا فِي أَهْلِهِ وَلَا يُجْلَسُ عَلَى ‏ ‏تَكْرِمَتِهِ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏فِي بَيْتِهِ إِلَّا بِإِذْنِهِ ‏ ‏أَوْ يَأْذَنَ لَكَ ‏","","",""],[16480,16480,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَرَأَ الْآيَتَيْنِ مِنْ آخِرِ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏فِي لَيْلَةٍ ‏ ‏كَفَتَاهُ ‏","","",""],[16481,16481,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَلَا لِحَيَاتِهِ ‏ ‏وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ تَعَالَى فَإِذَا رَأَيْتُمُوهُمَا فَصَلُّوا ‏","","",""],[16482,16482,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ عَبْدِ اللَّهِ بْنِ سَخْبَرَةَ الْأَزْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ مَنَاكِبَنَا فِي الصَّلَاةِ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏وَيَقُولُ اسْتَوُوا وَلَا تَخْتَلِفُوا ‏ ‏فَتَخْتَلِفَ قُلُوبُكُمْ لِيَلِيَنِّي مِنْكُمْ أُولُو ‏ ‏الْأَحْلَامِ ‏ ‏وَالنُّهَى ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏قَالَ ‏ ‏أَبُو مَسْعُودٍ ‏ ‏فَأَنْتُمْ الْيَوْمَ أَشَدُّ اخْتِلَافًا ‏","","",""],[16483,16483,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏وَابْنُ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي زَائِدَةَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُجْزِئُ صَلَاةٌ لِأَحَدٍ لَا يُقِيمُ فِيهَا ظَهْرَهُ فِي الرُّكُوعِ وَالسُّجُودِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[16484,16484,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏تَعْدِلُ ثُلُثَ الْقُرْآنِ ‏","","",""],[16485,16485,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى إِذَا لَمْ تَسْتَحْيِ فَافْعَلْ مَا شِئْتَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رِبْعِيَّ بْنَ حِرَاشٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[16486,16486,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ هُوَ ابْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيَعْجَزُ أَحَدُكُمْ أَنْ يَقْرَأَ ثُلُثَ الْقُرْآنِ فِي لَيْلَةٍ اللَّهُ الْوَاحِدُ الصَّمَدُ ‏","","",""],[16487,16487,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ الْأَنْصَارِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ الْبَدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا أَنْفَقَ عَلَى أَهْلِهِ نَفَقَةً وَهُوَ ‏ ‏يَحْتَسِبُهَا ‏ ‏كَانَتْ لَهُ ‏ ‏صَدَقَةً ‏","","",""],[16488,16488,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَيِّدُ ‏ ‏الِاسْتِغْفَارِ أَنْ يَقُولَ الْعَبْدُ ‏ ‏اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ‏ ‏أَبُوءُ ‏ ‏لَكَ بِالنِّعْمَةِ ‏ ‏وَأَبُوءُ ‏ ‏لَكَ بِذَنْبِي فَاغْفِرْ لِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ قَالَ إِنْ قَالَهَا بَعْدَمَا يُصْبِحُ ‏ ‏مُوقِنًا ‏ ‏بِهَا ثُمَّ مَاتَ كَانَ مِنْ أَهْلِ الْجَنَّةِ وَإِنْ قَالَهَا بَعْدَمَا يُمْسِي ‏ ‏مُوقِنًا ‏ ‏بِهَا ثُمَّ مَاتَ كَانَ مِنْ أَهْلِ الْجَنَّةِ ‏","","",""],[16489,16489,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏أَنَّهُ مَرَّ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَمَنَ الْفَتْحِ عَلَى رَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏بِالْبَقِيعِ ‏ ‏لِثَمَانِ عَشْرَةَ خَلَتْ مِنْ رَمَضَانَ وَهُوَ آخِذٌ بِيَدِي فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16490,16490,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏ثِنْتَانِ ‏ ‏حَفِظْتُهُمَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ وَلْيُحِدَّ أَحَدُكُمْ ‏ ‏شَفْرَتَهُ ‏ ‏وَلْيُرِحْ ذَبِيحَتَهُ ‏","","",""],[16491,16491,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏شَدَّادُ بْنُ أَوْسٍ ‏ ‏فِي سَفَرٍ فَنَزَلَ مَنْزِلًا فَقَالَ لِغُلَامِهِ ائْتِنَا ‏ ‏بِالشَّفْرَةِ ‏ ‏نَعْبَثْ بِهَا فَأَنْكَرْتُ عَلَيْهِ فَقَالَ مَا تَكَلَّمْتُ بِكَلِمَةٍ مُنْذُ أَسْلَمْتُ إِلَّا وَأَنَا ‏ ‏أَخْطِمُهَا ‏ ‏وَأَزُمُّهَا ‏ ‏إِلَّا كَلِمَتِي هَذِهِ فَلَا تَحْفَظُوهَا عَلَيَّ وَاحْفَظُوا مِنِّي مَا أَقُولُ لَكُمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا كَنَزَ النَّاسُ الذَّهَبَ وَالْفِضَّةَ فَاكْنِزُوا هَؤُلَاءِ الْكَلِمَاتِ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ وَالْعَزِيمَةَ عَلَى الرُّشْدِ وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ وَأَسْأَلُكَ حُسْنَ عِبَادَتِكَ وَأَسْأَلُكَ قَلْبًا سَلِيمًا وَأَسْأَلُكَ لِسَانًا صَادِقًا وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ ‏","","",""],[16492,16492,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏زَوَى ‏ ‏لِي الْأَرْضَ حَتَّى رَأَيْتُ مَشَارِقَهَا وَمَغَارِبَهَا وَإِنَّ مُلْكَ أُمَّتِي سَيَبْلُغُ مَا ‏ ‏زُوِيَ ‏ ‏لِي مِنْهَا وَإِنِّي أُعْطِيتُ الْكَنْزَيْنِ الْأَبْيَضَ وَالْأَحْمَرَ وَإِنِّي سَأَلْتُ رَبِّي عَزَّ وَجَلَّ لَا يُهْلِكُ أُمَّتِي بِسَنَةٍ بِعَامَّةٍ وَأَنْ لَا يُسَلِّطَ عَلَيْهِمْ عَدُوًّا فَيُهْلِكَهُمْ بِعَامَّةٍ وَأَنْ لَا يُلْبِسَهُمْ ‏ ‏شِيَعًا ‏ ‏وَلَا يُذِيقَ بَعْضَهُمْ بَأْسَ بَعْضٍ وَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي إِذَا قَضَيْتُ قَضَاءً فَإِنَّهُ لَا يُرَدُّ وَإِنِّي قَدْ أَعْطَيْتُكَ لِأُمَّتِكَ أَنْ لَا أُهْلِكَهُمْ بِسَنَةٍ بِعَامَّةٍ وَلَا أُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِمَّنْ سِوَاهُمْ فَيُهْلِكُوهُمْ بِعَامَّةٍ حَتَّى يَكُونَ بَعْضُهُمْ يُهْلِكُ بَعْضًا وَبَعْضُهُمْ يَقْتُلُ بَعْضًا وَبَعْضُهُمْ ‏ ‏يَسْبِي ‏ ‏بَعْضًا ‏","","",""],[16493,16493,"","","‏ ‏قَالَ ‏ ‏وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنِّي لَا أَخَافُ عَلَى أُمَّتِي إِلَّا الْأَئِمَّةَ الْمُضِلِّينَ فَإِذَا وُضِعَ السَّيْفُ فِي أُمَّتِي لَمْ يُرْفَعْ عَنْهُمْ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[16494,16494,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏حَفِظْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اثْنَتَيْنِ أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ وَلْيُحِدَّ أَحَدُكُمْ ‏ ‏شَفْرَتَهُ ‏ ‏ثُمَّ لِيُرِحْ ذَبِيحَتَهُ ‏","","",""],[16495,16495,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16496,16496,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ دَاوُدَ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏أَنَّهُ رَاحَ إِلَى مَسْجِدِ ‏ ‏دِمَشْقَ ‏ ‏وَهَجَّرَ ‏ ‏بِالرَّوَاحِ ‏ ‏فَلَقِيَ ‏ ‏شَدَّادَ بْنَ أَوْسٍ ‏ ‏وَالصُّنَابِحِيُّ ‏ ‏مَعَهُ فَقُلْتُ أَيْنَ تُرِيدَانِ يَرْحَمُكُمَا اللَّهُ قَالَا نُرِيدُ هَاهُنَا إِلَى أَخٍ لَنَا مَرِيضٍ نَعُودُهُ فَانْطَلَقْتُ مَعَهُمَا حَتَّى دَخَلَا عَلَى ذَلِكَ الرَّجُلِ فَقَالَا لَهُ كَيْفَ أَصْبَحْتَ قَالَ أَصْبَحْتُ بِنِعْمَةٍ فَقَالَ لَهُ ‏ ‏شَدَّادٌ ‏ ‏أَبْشِرْ بِكَفَّارَاتِ السَّيِّئَاتِ وَحَطِّ الْخَطَايَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏إِنِّي إِذَا ‏ ‏ابْتَلَيْتُ ‏ ‏عَبْدًا مِنْ عِبَادِي مُؤْمِنًا فَحَمِدَنِي عَلَى مَا ابْتَلَيْتُهُ فَإِنَّهُ يَقُومُ مِنْ مَضْجَعِهِ ذَلِكَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ مِنْ الْخَطَايَا وَيَقُولُ الرَّبُّ عَزَّ وَجَلَّ أَنَا قَيَّدْتُ عَبْدِي وَابْتَلَيْتُهُ وَأَجْرُوا لَهُ كَمَا كُنْتُمْ تُجْرُونَ لَهُ وَهُوَ صَحِيحٌ ‏","","",""],[16497,16497,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَمَانِ عَشْرَةَ لَيْلَةً خَلَتْ مِنْ رَمَضَانَ فَأَبْصَرَ رَجُلًا ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16498,16498,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَادَةُ بْنُ نُسَيٍّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏أَنَّهُ بَكَى فَقِيلَ لَهُ مَا ‏ ‏يُبْكِيكَ قَالَ شَيْئًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُهُ فَذَكَرْتُهُ فَأَبْكَانِي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَتَخَوَّفُ عَلَى أُمَّتِي الشِّرْكَ وَالشَّهْوَةَ الْخَفِيَّةَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَتُشْرِكُ أُمَّتُكَ مِنْ بَعْدِكَ قَالَ نَعَمْ أَمَا إِنَّهُمْ لَا يَعْبُدُونَ شَمْسًا وَلَا قَمَرًا وَلَا حَجَرًا وَلَا وَثَنًا وَلَكِنْ ‏ ‏يُرَاءُونَ ‏ ‏بِأَعْمَالِهِمْ وَالشَّهْوَةُ الْخَفِيَّةُ أَنْ يُصْبِحَ أَحَدُهُمْ صَائِمًا فَتَعْرِضُ لَهُ شَهْوَةٌ مِنْ شَهَوَاتِهِ فَيَتْرُكُ صَوْمَهُ ‏","","",""],[16499,16499,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ دَاوُدَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ شَدَّادٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي شَدَّادُ بْنُ أَوْسٍ ‏ ‏وَعُبَادَةُ بْنُ الصَّامِتِ ‏ ‏حَاضِرٌ يُصَدِّقُهُ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏هَلْ فِيكُمْ غَرِيبٌ ‏ ‏يَعْنِي ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏فَقُلْنَا لَا يَا رَسُولَ اللَّهِ فَأَمَرَ بِغَلْقِ الْبَابِ وَقَالَ ارْفَعُوا أَيْدِيَكُمْ وَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَرَفَعْنَا أَيْدِيَنَا سَاعَةً ثُمَّ وَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ ثُمَّ قَالَ الْحَمْدُ لِلَّهِ اللَّهُمَّ بَعَثْتَنِي بِهَذِهِ الْكَلِمَةِ وَأَمَرْتَنِي بِهَا وَوَعَدْتَنِي عَلَيْهَا الْجَنَّةَ وَإِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ثُمَّ قَالَ أَبْشِرُوا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ غَفَرَ لَكُمْ ‏","","",""],[16500,16500,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَيَكُونُ مِنْ بَعْدِي أَئِمَّةٌ ‏ ‏يُمِيتُونَ ‏ ‏الصَّلَاةَ عَنْ مَوَاقِيتِهَا فَصَلُّوا الصَّلَاةَ لِوَقْتِهَا وَاجْعَلُوا صَلَاتَكُمْ مَعَهُمْ سُبْحَةً ‏","","",""],[16501,16501,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَيِّسُ ‏ ‏مَنْ ‏ ‏دَانَ ‏ ‏نَفْسَهُ وَعَمِلَ لِمَا بَعْدَ الْمَوْتِ وَالْعَاجِزُ مَنْ أَتْبَعَ نَفْسَهُ هَوَاهَا وَتَمَنَّى عَلَى اللَّهِ ‏","","",""],[16502,16502,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا أَمْشِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏لِثَمَانِ عَشْرَةَ مَضَتْ مِنْ رَمَضَانَ وَهُوَ آخِذٌ بِيَدِي فَمَرَّ عَلَى رَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16503,16503,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ يَعْنِي القَصَّابَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ وَذَاكَ لِثَمَانِ عَشْرَةَ خَلَوْنَ مِنْ رَمَضَانَ فَأَبْصَرَ رَجُلًا ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16504,16504,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِرَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏فِي رَمَضَانَ فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16505,16505,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16506,16506,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ وَلْيُحِدَّنَّ أَحَدُكُمْ ‏ ‏شَفْرَتَهُ ‏ ‏وَلْيُرِحْ ذَبِيحَتَهُ ‏","","",""],[16507,16507,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ وَهُوَ أَبُو قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيَّ وَأَنَا ‏ ‏أَحْتَجِمُ ‏ ‏فِي ثَمَانِ عَشْرَةَ ‏ ‏خَلَوْنَ ‏ ‏مِنْ رَمَضَانَ فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16508,16508,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيِّدُ ‏ ‏الِاسْتِغْفَارِ ‏ ‏اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ قَالَ مَنْ قَالَهَا بَعْدَمَا يُصْبِحُ مُوقِنًا بِهَا فَمَاتَ مِنْ يَوْمِهِ كَانَ مِنْ أَهْلِ الْجَنَّةِ وَمَنْ قَالَهَا بَعْدَمَا يُمْسِي مُوقِنًا بِهَا فَمَاتَ مِنْ لَيْلَتِهِ كَانَ مِنْ أَهْلِ الْجَنَّةِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُشَيْرُ بْنُ كَعْبٍ الْعَدَوِيُّ ‏ ‏أَنَّ ‏ ‏شَدَّادَ بْنَ أَوْسٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَيِّدُ ‏ ‏الِاسْتِغْفَارِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[16509,16509,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَسْعُودٍ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنِ ‏ ‏الْحَنْظَلِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ رَجُلٍ يَأْوِي إِلَى فِرَاشِهِ فَيَقْرَأُ سُورَةً مِنْ كِتَابِ اللَّهِ عَزَّ وَجَلَّ إِلَّا بَعَثَ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ مَلَكًا يَحْفَظُهُ مِنْ كُلِّ شَيْءٍ ‏ ‏يُؤْذِيهِ حَتَّى ‏ ‏يَهُبَّ ‏ ‏مَتَى ‏ ‏هَبَّ ‏","","",""],[16510,16510,"","","‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا كَلِمَاتٍ ‏ ‏نَدْعُو بِهِنَّ فِي صَلَاتِنَا ‏ ‏أَوْ قَالَ فِي ‏ ‏دُبُرِ ‏ ‏صَلَاتِنَا ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ ‏ ‏الثَّبَاتَ ‏ ‏فِي الْأَمْرِ وَأَسْأَلُكَ عَزِيمَةَ الرُّشْدِ وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ وَحُسْنَ عِبَادَتِكَ وَأَسْأَلُكَ قَلْبًا سَلِيمًا وَلِسَانًا صَادِقًا وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ ‏","","",""],[16511,16511,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏قَزَعَةُ بْنُ سُوَيْدٍ الْبَاهِلِيُّ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْيَبُ ‏ ‏فَقَالَ عَنْ ‏ ‏أَبِي عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَرَضَ بَيْتَ شِعْرٍ بَعْدَ الْعِشَاءِ الْآخِرَةِ لَمْ تُقْبَلْ لَهُ صَلَاةٌ تِلْكَ اللَّيْلَةَ ‏","","",""],[16512,16512,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ بَهْرَامَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَهْرٌ يَعْنِي ابْنَ حَوْشَبٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ غَنْمٍ ‏ ‏أَنَّ ‏ ‏شَدَّادَ بْنَ أَوْسٍ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ حَدِيثِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَحْمِلَنَّ شِرَارُ هَذِهِ الْأُمَّةِ عَلَى سَنَنِ الَّذِينَ خَلَوْا مِنْ قَبْلِهِمْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏حَذْوَ ‏ ‏الْقُذَّةِ ‏ ‏بِالْقُذَّةِ ‏","","",""],[16513,16513,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَزَعَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُمَيْدٌ الْأَعْرَجُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَضَرْتُمْ مَوْتَاكُمْ فَأَغْمِضُوا الْبَصَرَ فَإِنَّ الْبَصَرَ يَتْبَعُ الرُّوحَ وَقُولُوا خَيْرًا فَإِنَّهُ يُؤَمَّنُ عَلَى مَا قَالَ أَهْلُ الْمَيِّتِ ‏","","",""],[16514,16514,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ الْأَشْيَبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَاهُ ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ قَالَ ‏ ‏شَدَّادُ بْنُ أَوْسٍ ‏ ‏كَانَ ‏ ‏أَبُو ذَرٍّ ‏ ‏يَسْمَعُ الْحَدِيثَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ الشِّدَّةُ ثُمَّ يَخْرُجُ إِلَى قَوْمِهِ يُسَلِّمُ لَعَلَّهُ يُشَدِّدُ عَلَيْهِمْ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَخِّصُ فِيهِ بَعْدُ فَلَمْ يَسْمَعْهُ ‏ ‏أَبُو ذَرٍّ ‏ ‏فَيَتَعَلَّقَ ‏ ‏أَبُو ذَرٍّ ‏ ‏بِالْأَمْرِ الشَّدِيدِ ‏","","",""],[16515,16515,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى رَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏فِي ‏ ‏الْبَقِيعِ ‏ ‏لِثَمَانِ عَشْرَةَ خَلَتْ مِنْ رَمَضَانَ وَهُوَ آخِذٌ بِيَدِي فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[16516,16516,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏ثِنْتَانِ حَفِظْتُهُمَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ وَلْيُحِدَّ أَحَدُكُمْ ‏ ‏شَفْرَتَهُ ‏ ‏وَلْيُرِحْ ذَبِيحَتَهُ ‏","","",""],[16517,16517,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ بَهْرَامَ ‏ ‏قَالَ قَالَ ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏قَالَ ‏ ‏ابْنُ غَنْمٍ ‏ ‏لَمَّا دَخَلْنَا مَسْجِدَ ‏ ‏الْجَابِيَةِ ‏ ‏أَنَا ‏ ‏وَأَبُو الدَّرْدَاءِ ‏ ‏لَقِينَا ‏ ‏عُبَادَةَ بْنَ الصَّامِتِ ‏ ‏فَأَخَذَ يَمِينِي بِشِمَالِهِ وَشِمَالَ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏بِيَمِينِهِ فَخَرَجَ يَمْشِي بَيْنَنَا وَنَحْنُ ‏ ‏نَنْتَجِي ‏ ‏وَاللَّهُ أَعْلَمُ فِيمَا ‏ ‏نَتَنَاجَى ‏ ‏وَذَاكَ قَوْلُهُ فَقَالَ ‏ ‏عُبَادَةُ بْنُ الصَّامِتِ ‏ ‏لَئِنْ طَالَ بِكُمَا عُمْرُ أَحَدِكُمَا أَوْ كِلَاكُمَا ‏ ‏لَيُوشِكَنَّ ‏ ‏أَنْ ‏ ‏تَرَيَا الرَّجُلَ مِنْ ‏ ‏ثَبَجِ ‏ ‏الْمُسْلِمِينَ ‏ ‏يَعْنِي مِنْ وَسَطٍ ‏ ‏قَرَأَ الْقُرْآنَ عَلَى لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعَادَهُ وَأَبْدَاهُ وَأَحَلَّ حَلَالَهُ وَحَرَّمَ حَرَامَهُ وَنَزَلَ عِنْدَ مَنَازِلِهِ أَوْ قَرَأَهُ عَلَى لِسَانِ أَخِيهِ قِرَاءَةً عَلَى لِسَانِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعَادَهُ وَأَبْدَاهُ وَأَحَلَّ حَلَالَهُ وَحَرَّمَ حَرَامَهُ وَنَزَلَ عِنْدَ مَنَازِلِهِ لَا ‏ ‏يَحُورُ ‏ ‏فِيكُمْ إِلَّا كَمَا ‏ ‏يَحُورُ ‏ ‏رَأْسُ الْحِمَارِ الْمَيِّتِ قَالَ فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ طَلَعَ ‏ ‏شَدَّادُ بْنُ أَوْسٍ ‏ ‏وعَوْفُ بْنُ مَالِكٍ ‏ ‏فَجَلَسَا إِلَيْنَا فَقَالَ ‏ ‏شَدَّادٌ ‏ ‏إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ أَيُّهَا النَّاسُ لَمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مِنْ الشَّهْوَةِ الْخَفِيَّةِ وَالشِّرْكِ فَقَالَ ‏ ‏عُبَادَةُ بْنُ الصَّامِتِ ‏ ‏وَأَبُو الدَّرْدَاءِ ‏ ‏اللَّهُمَّ غَفْرًا أَوَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ حَدَّثَنَا أَنَّ الشَّيْطَانَ قَدْ يَئِسَ أَنْ يُعْبَدَ فِي ‏ ‏جَزِيرَةِ الْعَرَبِ ‏ ‏فَأَمَّا الشَّهْوَةُ الْخَفِيَّةُ فَقَدْ عَرَفْنَاهَا هِيَ شَهَوَاتُ الدُّنْيَا مِنْ نِسَائِهَا وَشَهَوَاتِهَا فَمَا هَذَا الشِّرْكُ الَّذِي تُخَوِّفُنَا بِهِ يَا ‏ ‏شَدَّادُ ‏ ‏فَقَالَ ‏ ‏شَدَّادٌ ‏ ‏أَرَأَيْتُكُمْ لَوْ رَأَيْتُمْ رَجُلًا ‏ ‏يُصَلِّي لِرَجُلٍ أَوْ يَصُومُ لَهُ أَوْ يَتَصَدَّقُ لَهُ أَتَرَوْنَ أَنَّهُ قَدْ أَشْرَكَ قَالُوا نَعَمْ وَاللَّهِ إِنَّهُ مَنْ صَلَّى لِرَجُلٍ أَوْ صَامَ لَهُ أَوْ تَصَدَّقَ لَهُ لَقَدْ أَشْرَكَ فَقَالَ ‏ ‏شَدَّادٌ ‏ ‏فَإِنِّي قَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ صَلَّى ‏ ‏يُرَائِي ‏ ‏فَقَدْ أَشْرَكَ وَمَنْ صَامَ ‏ ‏يُرَائِي ‏ ‏فَقَدْ أَشْرَكَ وَمَنْ تَصَدَّقَ ‏ ‏يُرَائِي ‏ ‏فَقَدْ أَشْرَكَ فَقَالَ ‏ ‏عَوْفُ بْنُ مَالِكٍ ‏ ‏عِنْدَ ذَلِكَ أَفَلَا يَعْمِدُ إِلَى مَا ابْتُغِيَ فِيهِ وَجْهُهُ مِنْ ذَلِكَ الْعَمَلِ كُلِّهِ فَيَقْبَلَ مَا خَلَصَ لَهُ وَيَدَعَ مَا يُشْرَكُ بِهِ فَقَالَ ‏ ‏شَدَّادٌ ‏ ‏عِنْدَ ذَلِكَ فَإِنِّي قَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏أَنَا خَيْرُ ‏ ‏قَسِيمٍ ‏ ‏لِمَنْ أَشْرَكَ بِي مَنْ أَشْرَكَ بِي شَيْئًا فَإِنَّ حَشْدَهُ عَمَلَهُ قَلِيلَهُ وَكَثِيرَهُ لِشَرِيكِهِ الَّذِي أَشْرَكَ بِهِ وَأَنَا عَنْهُ غَنِيٌّ ‏","","",""],[16518,16518,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَغْفِرُ لِلصَّفِّ الْمُقَدَّمِ ثَلَاثًا وَلِلثَّانِي مَرَّةً ‏","","",""],[16519,16519,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو السُّلَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْعِرْبَاضَ بْنَ سَارِيَةَ ‏ ‏قَالَ ‏ ‏وَعَظَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَوْعِظَةً ‏ ‏ذَرَفَتْ ‏ ‏مِنْهَا الْعُيُونُ ‏ ‏وَوَجِلَتْ ‏ ‏مِنْهَا الْقُلُوبُ قُلْنَا يَا رَسُولَ اللَّهِ إِنَّ هَذِهِ لَمَوْعِظَةُ مُوَدِّعٍ فَمَاذَا تَعْهَدُ إِلَيْنَا قَالَ ‏ ‏قَدْ تَرَكْتُكُمْ عَلَى الْبَيْضَاءِ لَيْلُهَا كَنَهَارِهَا لَا يَزِيغُ عَنْهَا بَعْدِي إِلَّا هَالِكٌ وَمَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا فَعَلَيْكُمْ بِمَا عَرَفْتُمْ مِنْ سُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ وَعَلَيْكُمْ بِالطَّاعَةِ وَإِنْ عَبْدًا حَبَشِيًّا عَضُّوا عَلَيْهَا ‏ ‏بِالنَّوَاجِذِ ‏ ‏فَإِنَّمَا الْمُؤْمِنُ كَالْجَمَلِ ‏ ‏الْأَنِفِ ‏ ‏حَيْثُمَا انْقِيدَ انْقَادَ ‏","","",""],[16520,16520,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ الْخَيَّاطُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ سَيْفٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي رُهْمٍ ‏ ‏عَنْ ‏ ‏عِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى السَّحُورِ فِي رَمَضَانَ فَقَالَ ‏ ‏هَلُمَّ إِلَى هَذَا الْغِذَاءِ الْمُبَارَكِ ‏","","",""],[16521,16521,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏صَلَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَجْرَ ثُمَّ أَقْبَلَ عَلَيْنَا فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً ‏ ‏ذَرَفَتْ ‏ ‏لَهَا الْأَعْيُنُ ‏ ‏وَوَجِلَتْ ‏ ‏مِنْهَا الْقُلُوبُ قُلْنَا ‏ ‏أَوْ قَالُوا ‏ ‏يَا رَسُولَ اللَّهِ كَأَنَّ هَذِهِ مَوْعِظَةُ مُوَدِّعٍ فَأَوْصِنَا قَالَ ‏ ‏أُوصِيكُمْ بِتَقْوَى اللَّهِ وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ كَانَ عَبْدًا حَبَشِيًّا فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ يَرَى بَعْدِي اخْتِلَافًا كَثِيرًا فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ وَعَضُّوا عَلَيْهَا ‏ ‏بِالنَّوَاجِذِ ‏ ‏وَإِيَّاكُمْ ‏ ‏وَمُحْدَثَاتِ ‏ ‏الْأُمُورِ فَإِنَّ كُلَّ ‏ ‏مُحْدَثَةٍ ‏ ‏بِدْعَةٌ وَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ ‏","","",""],[16522,16522,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَعْدَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَمْرٍو السُّلَمِيُّ ‏ ‏وَحُجْرُ بْنُ حُجْرٍ ‏ ‏قَالَا ‏ ‏أَتَيْنَا ‏ ‏الْعِرْبَاضَ بْنَ سَارِيَةَ ‏ ‏وَهُوَ ‏ ‏مِمَّنْ نَزَلَ فِيهِ ‏ { ‏وَلَا عَلَى الَّذِينَ إِذَا مَا أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَا أَجِدُ مَا أَحْمِلُكُمْ عَلَيْهِ ‏} ‏فَسَلَّمْنَا وَقُلْنَا أَتَيْنَاكَ زَائِرِينَ وَعَائِدِينَ ‏ ‏وَمُقْتَبِسِينَ ‏ ‏فَقَالَ ‏ ‏عِرْبَاضٌ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ ذَاتَ يَوْمٍ ثُمَّ أَقْبَلَ عَلَيْنَا فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً ‏ ‏ذَرَفَتْ ‏ ‏مِنْهَا الْعُيُونُ ‏ ‏وَوَجِلَتْ ‏ ‏مِنْهَا الْقُلُوبُ فَقَالَ قَائِلٌ يَا رَسُولَ اللَّهِ كَأَنَّ هَذِهِ مَوْعِظَةُ مُوَدِّعٍ فَمَاذَا تَعْهَدُ إِلَيْنَا فَقَالَ ‏ ‏أُوصِيكُمْ بِتَقْوَى اللَّهِ وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ كَانَ عَبْدًا حَبَشِيًّا فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ بَعْدِي فَسَيَرَى اخْتِلَافًا كَثِيرًا فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ فَتَمَسَّكُوا بِهَا وَعَضُّوا عَلَيْهَا ‏ ‏بِالنَّوَاجِذِ ‏ ‏وَإِيَّاكُمْ ‏ ‏وَمُحْدَثَاتِ ‏ ‏الْأُمُورِ فَإِنَّ كُلَّ مُحْدَثَةٍ بِدْعَةٌ وَكُلَّ بِدْعَةٍ ضَلَالَةٌ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي بِلَالٍ ‏ ‏عَنْ ‏ ‏عِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏أَنَّهُ حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَظَهُمْ يَوْمًا بَعْدَ صَلَاةِ الْغَدَاةِ فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي بِلَالٍ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏أَنَّهُ حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَظَهُمْ يَوْمًا بَعْدَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏فَذَكَرَهُ ‏","","",""],[16523,16523,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏أَنَّهُ حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَغْفِرُ لِلصَّفِّ الْمُقَدَّمِ ثَلَاثَ مِرَارٍ وَلِلثَّانِي مَرَّةً ‏","","",""],[16524,16524,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ هَانِئٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعِرْبَاضَ بْنَ سَارِيَةَ ‏ ‏قَالَ ‏ ‏بِعْتُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَكْرًا ‏ ‏فَأَتَيْتُهُ ‏ ‏أَتَقَاضَاهُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ اقْضِنِي ثَمَنَ ‏ ‏بَكْرِي ‏ ‏فَقَالَ أَجَلْ لَا ‏ ‏أَقْضِيكَهَا ‏ ‏إِلَّا ‏ ‏لُجَيْنِيَّةً ‏ ‏قَالَ فَقَضَانِي فَأَحْسَنَ ‏ ‏قَضَائِي ‏ ‏قَالَ وَجَاءَهُ أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ اقْضِنِي ‏ ‏بَكْرِي ‏ ‏فَأَعْطَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ جَمَلًا قَدْ ‏ ‏أَسَنَّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ هَذَا خَيْرٌ مِنْ ‏ ‏بَكْرِي ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ خَيْرَ الْقَوْمِ خَيْرُهُمْ قَضَاءً ‏","","",""],[16525,16525,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سُوَيْدٍ الْكَلْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هِلَالٍ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي عَبْدُ اللَّهِ لَخَاتَمُ النَّبِيِّينَ وَإِنَّ ‏ ‏آدَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏لَمُنْجَدِلٌ ‏ ‏فِي طِينَتِهِ وَسَأُنَبِّئُكُمْ بِأَوَّلِ ذَلِكَ دَعْوَةُ أَبِي ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبِشَارَةُ ‏ ‏عِيسَى ‏ ‏بِي وَرُؤْيَا أُمِّي الَّتِي رَأَتْ وَكَذَلِكَ ‏ ‏أُمَّهَاتُ النَّبِيِّينَ تَرَيْنَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ وَهُوَ الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى بْنِ هِلَالٍ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنِّي عَبْدُ اللَّهِ وَخَاتَمُ النَّبِيِّينَ فَذَكَرَ مِثْلَهُ وَزَادَ فِيهِ إِنَّ أُمَّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَتْ حِينَ وَضَعَتْهُ نُورًا أَضَاءَتْ مِنْهُ قُصُورُ ‏ ‏الشَّامِ ‏","","",""],[16526,16526,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ سَيْفٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي رُهْمٍ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَدْعُونَا إِلَى السَّحُورِ فِي شَهْرِ رَمَضَانَ ‏ ‏هَلُمُّوا إِلَى الْغِذَاءِ الْمُبَارَكِ ثُمَّ سَمِعْتُهُ يَقُولُ اللَّهُمَّ عَلِّمْ ‏ ‏مُعَاوِيَةَ ‏ ‏الْكِتَابَ وَالْحِسَابَ وَقِهِ الْعَذَابَ ‏","","",""],[16527,16527,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ خَالِدٍ الْحِمْصِيُّ ‏ ‏حَدَّثَتْنِي ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ الْعِرْبَاضِ ‏ ‏قَالَتْ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏كُلَّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ وَلُحُومَ الْحُمُرِ الْأَهْلِيَّةِ ‏ ‏وَالْخَلِيسَةَ ‏ ‏وَالْمُجَثَّمَةَ ‏ ‏وَأَنْ ‏ ‏تُوطَأَ ‏ ‏السَّبَايَا ‏ ‏حَتَّى يَضَعْنَ مَا فِي بُطُونِهِنَّ ‏","","",""],[16528,16528,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبٌ أَبُو خَالِدٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ الْعِرْبَاضِ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْخُذُ ‏ ‏الْوَبَرَةَ ‏ ‏مِنْ ‏ ‏قُصَّةٍ ‏ ‏مِنْ ‏ ‏فَيْءِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏ ‏فَيَقُولُ ‏ ‏مَا لِي مِنْ هَذَا إِلَّا مِثْلَ مَا لِأَحَدِكُمْ إِلَّا الْخُمُسَ وَهُوَ مَرْدُودٌ فِيكُمْ فَأَدُّوا الْخَيْطَ ‏ ‏وَالْمَخِيطَ ‏ ‏فَمَا فَوْقَهُمَا وَإِيَّاكُمْ ‏ ‏وَالْغُلُولَ ‏ ‏فَإِنَّهُ ‏ ‏عَارٌ ‏ ‏وَشَنَارٌ ‏ ‏عَلَى صَاحِبِهِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَرَوَى ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ ‏ ‏عَنْ ‏ ‏وَهْبٍ ‏ ‏هَذَا ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏عَبْدُ الْأَعْلَى بْنُ هِلَالٍ ‏ ‏هُوَ الصَّوَابُ ‏","","",""],[16529,16529,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ وَهُوَ مُحَمَّدُ بْنُ جَعْفَرٍ الْمَدَائِنِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الرَّجُلَ إِذَا سَقَى امْرَأَتَهُ مِنْ الْمَاءِ أُجِرَ ‏ ‏قَالَ ‏ ‏فَأَتَيْتُهَا فَسَقَيْتُهَا وَحَدَّثْتُهَا بِمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16530,16530,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏جُبَيْرَ بْنَ نُفَيْرٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏الْعِرْبَاضَ ‏ ‏حَدَّثَهُ ‏ ‏وَكَانَ ‏ ‏الْعِرْبَاضُ بْنُ سَارِيَةَ ‏ ‏مِنْ ‏ ‏أَصْحَابِ الصُّفَّةِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى الصَّفِّ الْمُقَدَّمِ ثَلَاثًا وَعَلَى الثَّانِي وَاحِدَةً ‏","","",""],[16531,16531,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي عَلَى الصَّفِّ الْأَوَّلِ ثَلَاثًا وَعَلَى الَّذِي يَلِيهِ وَاحِدَةً ‏","","",""],[16532,16532,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ يَعْنِي إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الْمُتَحَابُّونَ بِجَلَالِي فِي ظِلِّ عَرْشِي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَأَحْسَبُنِي قَدْ سَمِعْتُهُ مِنْهُ ‏","","",""],[16533,16533,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ يَعْنِي ابْنَ يَزِيدَ الْحَضْرَمِيَّ ‏ ‏وَيَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي بِلَالٍ ‏ ‏عَنْ ‏ ‏عِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَخْتَصِمُ الشُّهَدَاءُ وَالْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ إِلَى رَبِّنَا عَزَّ وَجَلَّ فِي الَّذِينَ يُتَوَفَّوْنَ مِنْ الطَّاعُونِ فَيَقُولُ الشُّهَدَاءُ إِخْوَانُنَا قُتِلُوا كَمَا قُتِلْنَا وَيَقُولُ الْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ إِخْوَانُنَا مَاتُوا عَلَى فُرُشِهِمْ كَمَا مِتْنَا عَلَى فُرُشِنَا فَيَقُولُ الرَّبُّ عَزَّ وَجَلَّ ‏ ‏انْظُرُوا إِلَى جِرَاحِهِمْ فَإِنْ أَشْبَهَتْ جِرَاحُهُمْ جِرَاحَ الْمَقْتُولِينَ فَإِنَّهُمْ مِنْهُمْ وَمَعَهُمْ فَإِذَا جِرَاحُهُمْ قَدْ أَشْبَهَتْ جِرَاحَهُمْ ‏","","",""],[16534,16534,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي بِلَالٍ ‏ ‏عَنْ ‏ ‏عِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏أَنَّهُ حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ ‏ ‏الْمُسَبِّحَاتِ ‏ ‏قَبْلَ أَنْ يَرْقُدَ وَقَالَ إِنَّ فِيهِنَّ آيَةً أَفْضَلُ مِنْ أَلْفِ آيَةٍ ‏","","",""],[16535,16535,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏ضَمْضَمِ بْنِ زُرْعَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ عُبَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏الْعِرْبَاضُ بْنُ سَارِيَةَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ عَلَيْنَا فِي ‏ ‏الصُّفَّةِ ‏ ‏وَعَلَيْنَا ‏ ‏الْحَوْتَكِيَّةُ ‏ ‏فَيَقُولُ ‏ ‏لَوْ تَعْلَمُونَ مَا ‏ ‏ذُخِرَ ‏ ‏لَكُمْ مَا حَزِنْتُمْ عَلَى مَا ‏ ‏زُوِيَ ‏ ‏عَنْكُمْ وَلَيُفْتَحَنَّ لَكُمْ ‏ ‏فَارِسُ ‏ ‏وَالرُّومُ ‏","","",""],[16536,16536,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الصَّفِّ الْمُقَدَّمِ ثَلَاثًا وَعَلَى الَّذِي يَلِيهِ وَاحِدَةً ‏","","",""],[16537,16537,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سُوَيْدٍ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي عَبْدُ اللَّهِ فِي أُمِّ الْكِتَابِ لَخَاتَمُ النَّبِيِّينَ وَإِنَّ ‏ ‏آدَمَ ‏ ‏لَمُنْجَدِلٌ ‏ ‏فِي طِينَتِهِ وَسَأُنَبِّئُكُمْ ‏ ‏بِتَأْوِيلِ ‏ ‏ذَلِكَ دَعْوَةِ أَبِي ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبِشَارَةِ ‏ ‏عِيسَى ‏ ‏قَوْمَهُ وَرُؤْيَا أُمِّي الَّتِي رَأَتْ أَنَّهُ خَرَجَ مِنْهَا نُورٌ أَضَاءَتْ لَهُ قُصُورُ ‏ ‏الشَّامِ ‏ ‏وَكَذَلِكَ ‏ ‏تَرَى ‏ ‏أُمَّهَاتُ النَّبِيِّينَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِمْ ‏","","",""],[16538,16538,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي بِلَالٍ ‏ ‏عَنِ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَخْتَصِمُ الشُّهَدَاءُ وَالْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ إِلَى اللَّهِ عَزَّ وَجَلَّ فِي الَّذِينَ مَاتُوا مِنْ الطَّاعُونِ فَيَقُولُ الشُّهَدَاءُ إِخْوَانُنَا قُتِلُوا وَيَقُولُ الْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ إِخْوَانُنَا مَاتُوا عَلَى فُرُشِهِمْ كَمَا مِتْنَا ‏ ‏فَيَقْضِي اللَّهُ عَزَّ وَجَلَّ بَيْنَهُمْ ‏ ‏أَنْ انْظُرُوا إِلَى جِرَاحَاتِ الْمُطَّعَنِينَ فَإِنْ أَشْبَهَتْ جِرَاحَاتِ الشُّهَدَاءِ فَهُمْ مِنْهُمْ فَيَنْظُرُونَ إِلَى جِرَاحِ الْمُطَّعَنِينَ فَإِذَا هُمْ قَدْ أَشْبَهَتْ فَيُلْحَقُونَ مَعَهُمْ ‏","","",""],[16539,16539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُدْرِكٍ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ قُتِلَ مِنْهُمْ ‏ ‏بِأَوْطَاسٍ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا عَامِرٍ ‏ ‏أَلَا غَيَّرْتَ فَتَلَا هَذِهِ الْآيَةَ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنْفُسَكُمْ لَا يَضُرُّكُمْ مَنْ ضَلَّ إِذَا اهْتَدَيْتُمْ ‏} ‏فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ أَيْنَ ذَهَبْتُمْ إِنَّمَا هِيَ يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَضُرُّكُمْ مَنْ ضَلَّ مِنْ الْكُفَّارِ إِذَا اهْتَدَيْتُمْ ‏","","",""],[16540,16540,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَلَاذٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏نُمَيْرِ بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ مَسْرُوحٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ أَبِي عَامِرٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نِعْمَ الْحَيُّ ‏ ‏الْأُسْدُ ‏ ‏وَالْأَشْعَرِيُّونَ ‏ ‏لَا يَفِرُّونَ فِي الْقِتَالِ وَلَا ‏ ‏يَغُلُّونَ ‏ ‏هُمْ مِنِّي وَأَنَا مِنْهُمْ ‏ ‏قَالَ ‏ ‏عَامِرٌ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ لَيْسَ هَكَذَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنَّهُ قَالَ هُمْ مِنِّي وَإِلَيَّ فَقَالَ لَيْسَ هَكَذَا ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنَّهُ قَالَ ‏ ‏هُمْ مِنِّي وَأَنَا مِنْهُمْ قَالَ فَأَنْتَ إِذًا أَعْلَمُ بِحَدِيثِ أَبِيكَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏هَذَا مِنْ أَجْوَدِ الْحَدِيثِ مَا رَوَاهُ إِلَّا ‏ ‏جَرِيرٌ ‏","","",""],[16541,16541,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي حُسَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏أَوْ ‏ ‏أَبِي عَامِرٍ ‏ ‏أَوْ ‏ ‏أَبِي مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا هُوَ جَالِسٌ فِي مَجْلِسٍ فِيهِ أَصْحَابُهُ جَاءَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فِي غَيْرِ صُورَتِهِ يَحْسِبُهُ رَجُلًا مِنْ الْمُسْلِمِينَ فَسَلَّمَ عَلَيْهِ فَرَدَّ عَلَيْهِ السَّلَامَ ثُمَّ وَضَعَ ‏ ‏جِبْرِيلُ ‏ ‏يَدَهُ عَلَى رُكْبَتَيْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ لَهُ يَا رَسُولَ اللَّهِ ‏ ‏مَا الْإِسْلَامُ فَقَالَ أَنْ تُسْلِمَ وَجْهَكَ لِلَّهِ وَأَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ وَتُقِيمَ الصَّلَاةَ وَتُؤْتِيَ الزَّكَاةَ قَالَ فَإِذَا فَعَلْتُ ذَلِكَ فَقَدْ أَسْلَمْتُ قَالَ نَعَمْ ثُمَّ قَالَ مَا الْإِيمَانُ قَالَ أَنْ تُؤْمِنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَالْمَلَائِكَةِ وَالْكِتَابِ وَالنَّبِيِّينَ وَالْمَوْتِ وَالْحَيَاةِ بَعْدَ الْمَوْتِ وَالْجَنَّةِ وَالنَّارِ وَالْحِسَابِ وَالْمِيزَانِ وَالْقَدَرِ كُلِّهِ خَيْرِهِ وَشَرِّهِ قَالَ فَإِذَا فَعَلْتُ ذَلِكَ فَقَدْ آمَنْتُ قَالَ نَعَمْ ثُمَّ قَالَ مَا الْإِحْسَانُ يَا رَسُولَ اللَّهِ قَالَ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنَّكَ إِنْ كُنْتَ لَا تَرَاهُ فَهُوَ يَرَاكَ قَالَ فَإِذَا فَعَلْتُ ذَلِكَ فَقَدْ أَحْسَنْتُ قَالَ نَعَمْ وَنَسْمَعُ رَجْعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ وَلَا يُرَى الَّذِي يُكَلِّمُهُ وَلَا يُسْمَعُ كَلَامُهُ قَالَ فَمَتَى السَّاعَةُ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَانَ اللَّهِ خَمْسٌ مِنْ الْغَيْبِ لَا يَعْلَمُهَا إِلَّا اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏} ‏فَقَالَ السَّائِلُ يَا رَسُولَ اللَّهِ إِنْ شِئْتَ حَدَّثْتُكَ بِعَلَامَتَيْنِ تَكُونَانِ قَبْلَهَا فَقَالَ حَدِّثْنِي فَقَالَ إِذَا رَأَيْتَ ‏ ‏الْأَمَةَ ‏ ‏تَلِدُ ‏ ‏رَبَّهَا ‏ ‏وَيَطُولُ أَهْلُ الْبُنْيَانِ بِالْبُنْيَانِ وَعَادَ ‏ ‏الْعَالَةُ ‏ ‏الْحُفَاةُ رُءُوسَ النَّاسِ قَالَ وَمَنْ أُولَئِكَ يَا رَسُولَ اللَّهِ قَالَ الْعَرِيبُ قَالَ ثُمَّ ‏ ‏وَلَّى ‏ ‏فَلَمَّا لَمْ نَرَ طَرِيقَهُ بَعْدُ قَالَ سُبْحَانَ اللَّهِ ثَلَاثًا هَذَا ‏ ‏جِبْرِيلُ ‏ ‏جَاءَ لِيُعَلِّمَ النَّاسَ دِينَهُمْ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ مَا جَاءَنِي قَطُّ إِلَّا وَأَنَا أَعْرِفُهُ إِلَّا أَنْ تَكُونَ هَذِهِ الْمَرَّةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَصْنَافِ النِّسَاءِ وَذَكَرَ الْحَدِيثَ وَذَكَرَ مُلْصِقًا بِهِ قَالَ جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَجْلِسًا فَأَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَجَلَسَ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ وَقَالَ فِيهِ إِنْ شِئْتَ حَدَّثْتُكَ بِمَعَالِمَ لَهَا دُونَ ذَلِكَ قَالَ أَجَلْ يَا رَسُولَ اللَّهِ فَحَدِّثْنِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتَ ‏ ‏الْأَمَةَ ‏ ‏وَلَدَتْ ‏ ‏رَبَّتَهَا ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[16542,16542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَلَفٍ مُوسَى بْنُ خَلَفٍ ‏ ‏كَانَ يُعَدُّ فِي الْبُدَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ سَلَّامٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏مَمْطُورٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ الْأَشْعَرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ أَمَرَ ‏ ‏يَحْيَى بْنَ زَكَرِيَّا ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏بِخَمْسِ كَلِمَاتٍ أَنْ يَعْمَلَ بِهِنَّ وَأَنْ يَأْمُرَ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏أَنْ يَعْمَلُوا بِهِنَّ وَكَادَ أَنْ يُبْطِئَ فَقَالَ لَهُ ‏ ‏عِيسَى ‏ ‏إِنَّكَ قَدْ أُمِرْتَ بِخَمْسِ كَلِمَاتٍ أَنْ تَعْمَلَ بِهِنَّ وَتَأْمُرَ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏أَنْ يَعْمَلُوا بِهِنَّ فَإِمَّا أَنْ تُبَلِّغَهُنَّ وَإِمَّا أَنْ أُبَلِّغَهُنَّ فَقَالَ يَا أَخِي إِنِّي أَخْشَى إِنْ سَبَقْتَنِي أَنْ أُعَذَّبَ أَوْ يُخْسَفَ بِي قَالَ فَجَمَعَ ‏ ‏يَحْيَى ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فِي ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏حَتَّى امْتَلَأَ الْمَسْجِدُ فَقُعِدَ عَلَى الشُّرَفِ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَمَرَنِي بِخَمْسِ كَلِمَاتٍ أَنْ أَعْمَلَ بِهِنَّ وَآمُرَكُمْ أَنْ تَعْمَلُوا بِهِنَّ أَوَّلُهُنَّ أَنْ تَعْبُدُوا اللَّهَ لَا تُشْرِكُوا بِهِ شَيْئًا فَإِنَّ مَثَلَ ذَلِكَ مَثَلُ رَجُلٍ اشْتَرَى عَبْدًا مِنْ خَالِصِ مَالِهِ بِوَرِقٍ أَوْ ذَهَبٍ فَجَعَلَ يَعْمَلُ وَيُؤَدِّي ‏ ‏غَلَّتَهُ ‏ ‏إِلَى غَيْرِ سَيِّدِهِ فَأَيُّكُمْ سَرَّهُ أَنْ يَكُونَ عَبْدُهُ كَذَلِكَ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَكُمْ وَرَزَقَكُمْ فَاعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَآمُرُكُمْ بِالصَّلَاةِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يَنْصِبُ ‏ ‏وَجْهَهُ لِوَجْهِ عَبْدِهِ مَا لَمْ يَلْتَفِتْ فَإِذَا صَلَّيْتُمْ فَلَا تَلْتَفِتُوا وَآمُرُكُمْ بِالصِّيَامِ فَإِنَّ مَثَلَ ذَلِكَ كَمَثَلِ رَجُلٍ مَعَهُ صُرَّةٌ مِنْ مِسْكٍ فِي ‏ ‏عِصَابَةٍ ‏ ‏كُلُّهُمْ يَجِدُ رِيحَ الْمِسْكِ وَإِنَّ ‏ ‏خُلُوفَ ‏ ‏فَمِ الصَّائِمِ عِنْدَ اللَّهِ أَطْيَبُ مِنْ رِيحِ الْمِسْكِ وَآمُرُكُمْ بِالصَّدَقَةِ فَإِنَّ مَثَلَ ذَلِكَ كَمَثَلِ رَجُلٍ أَسَرَهُ الْعَدُوُّ فَشَدُّوا يَدَيْهِ إِلَى عُنُقِهِ وَقَدَّمُوهُ لِيَضْرِبُوا عُنُقَهُ فَقَالَ هَلْ لَكُمْ أَنْ أَفْتَدِيَ نَفْسِي مِنْكُمْ فَجَعَلَ ‏ ‏يَفْتَدِي نَفْسَهُ مِنْهُمْ بِالْقَلِيلِ وَالْكَثِيرِ حَتَّى فَكَّ نَفْسَهُ وَآمُرُكُمْ بِذِكْرِ اللَّهِ عَزَّ وَجَلَّ كَثِيرًا وَإِنَّ مَثَلَ ذَلِكَ كَمَثَلِ رَجُلٍ طَلَبَهُ الْعَدُوُّ سِرَاعًا فِي أَثَرِهِ فَأَتَى حِصْنًا حَصِينًا فَتَحَصَّنَ فِيهِ وَإِنَّ الْعَبْدَ أَحْصَنُ مَا يَكُونُ مِنْ الشَّيْطَانِ إِذَا كَانَ فِي ذِكْرِ اللَّهِ عَزَّ وَجَلَّ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا آمُرُكُمْ بِخَمْسٍ اللَّهُ أَمَرَنِي بِهِنَّ بِالْجَمَاعَةِ وَالسَّمْعِ وَالطَّاعَةِ وَالْهِجْرَةِ وَالْجِهَادِ فِي سَبِيلِ اللَّهِ فَإِنَّهُ مَنْ خَرَجَ مِنْ الْجَمَاعَةِ قِيدَ شِبْرٍ فَقَدْ خَلَعَ ‏ ‏رِبْقَةَ ‏ ‏الْإِسْلَامِ مِنْ عُنُقِهِ إِلَّا أَنْ يَرْجِعَ وَمَنْ دَعَا بِدَعْوَى الْجَاهِلِيَّةِ فَهُوَ مِنْ جُثَاءِ جَهَنَّمَ قَالُوا يَا رَسُولَ اللَّهِ وَإِنْ صَامَ وَإِنْ صَلَّى قَالَ وَإِنْ صَامَ وَإِنْ صَلَّى وَزَعَمَ أَنَّهُ مُسْلِمٌ فَادْعُوا الْمُسْلِمِينَ بِأَسْمَائِهِمْ بِمَا سَمَّاهُمْ اللَّهُ عَزَّ وَجَلَّ الْمُسْلِمِينَ الْمُؤْمِنِينَ عِبَادَ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[16543,16543,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَوْرٌ يَعْنِي ابْنَ يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَبِيبُ بْنُ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ أَبِي كَرِيمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَحَبَّ أَحَدُكُمْ أَخَاهُ فَلْيُعْلِمْهُ أَنَّهُ يُحْبِبْهُ ‏","","",""],[16544,16544,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ أَبِي كَرِيمَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْلَةُ الضَّيْفِ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ فَإِنْ أَصْبَحَ بِفِنَائِهِ مَحْرُومًا كَانَ دَيْنًا لَهُ عَلَيْهِ إِنْ شَاءَ اقْتَضَاهُ وَإِنْ شَاءَ تَرَكَهُ ‏","","",""],[16545,16545,"","","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي كَرِيمَةَ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةُ الضَّيْفِ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ فَإِنْ أَصْبَحَ بِفِنَائِهِ مَحْرُومًا كَانَ دَيْنًا لَهُ عَلَيْهِ إِنْ شَاءَ اقْتَضَاهُ وَإِنْ شَاءَ تَرَكَهُ ‏","","",""],[16546,16546,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَوْفٍ الْجُرَشِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ الْكِنْدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا إِنِّي أُوتِيتُ الْكِتَابَ وَمِثْلَهُ مَعَهُ أَلَا إِنِّي أُوتِيتُ الْقُرْآنَ وَمِثْلَهُ مَعَهُ لَا يُوشِكُ رَجُلٌ ‏ ‏يَنْثَنِي ‏ ‏شَبْعَانًا عَلَى ‏ ‏أَرِيكَتِهِ ‏ ‏يَقُولُ عَلَيْكُمْ بِالْقُرْآنِ فَمَا وَجَدْتُمْ فِيهِ مِنْ حَلَالٍ فَأَحِلُّوهُ وَمَا وَجَدْتُمْ فِيهِ مِنْ حَرَامٍ فَحَرِّمُوهُ أَلَا لَا يَحِلُّ لَكُمْ لَحْمُ الْحِمَارِ الْأَهْلِيِّ وَلَا كُلُّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ أَلَا وَلَا ‏ ‏لُقَطَةٌ ‏ ‏مِنْ مَالِ ‏ ‏مُعَاهَدٍ ‏ ‏إِلَّا أَنْ يَسْتَغْنِيَ عَنْهَا صَاحِبُهَا وَمَنْ نَزَلَ بِقَوْمٍ فَعَلَيْهِمْ أَنْ ‏ ‏يَقْرُوهُمْ ‏ ‏فَإِنْ لَمْ ‏ ‏يَقْرُوهُمْ ‏ ‏فَلَهُمْ أَنْ ‏ ‏يُعْقِبُوهُمْ ‏ ‏بِمِثْلِ ‏ ‏قِرَاهُمْ ‏","","",""],[16547,16547,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ الْهَوْزَنِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ أَبِي كَرِيمَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَرَكَ ‏ ‏كَلًّا ‏ ‏فَإِلَى اللَّهِ وَرَسُولِهِ ‏ ‏وَرُبَّمَا قَالَ فَإِلَيْنَا ‏ ‏وَمَنْ تَرَكَ مَالًا فَلِوَارِثِهِ وَالْخَالُ وَارِثُ مَنْ لَا وَارِثَ لَهُ وَأَنَا وَارِثُ مَنْ لَا وَارِثَ لَهُ أَرِثُهُ ‏ ‏وَأَعْقِلُ ‏ ‏عَنْهُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرَهُ ‏ ‏وَقَالَ عَنِ ‏ ‏الْمِقْدَامِ ‏ ‏مِنْ ‏ ‏كِنْدَةَ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[16548,16548,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِيلُوا طَعَامَكُمْ يُبَارَكْ لَكُمْ فِيهِ ‏","","",""],[16549,16549,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْجُودِيِّ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ الْمُهَاجِرِ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ أَبِي كَرِيمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا مُسْلِمٍ أَضَافَ قَوْمًا فَأَصْبَحَ الضَّيْفُ مَحْرُومًا فَإِنَّ حَقٌّ عَلَى كُلِّ مُسْلِمٍ نَصْرَهُ حَتَّى يَأْخُذَ ‏ ‏بِقِرَى ‏ ‏لَيْلَتِهِ مِنْ زَرْعِهِ وَمَالِهِ ‏","","",""],[16550,16550,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَطْعَمْتَ نَفْسَكَ فَهُوَ لَكَ ‏ ‏صَدَقَةٌ ‏ ‏وَمَا أَطْعَمْتَ وَلَدَكَ فَهُوَ لَكَ ‏ ‏صَدَقَةٌ ‏ ‏وَمَا أَطْعَمْتَ زَوْجَكَ فَهُوَ لَكَ ‏ ‏صَدَقَةٌ ‏ ‏وَمَا أَطْعَمْتَ خَادِمَكَ فَهُوَ لَكَ ‏ ‏صَدَقَةٌ ‏","","",""],[16551,16551,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَرْطَاةَ بْنِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏بَعْضِ أَشْيَاخِ الْجُنْدِ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ لَطْمِ خُدُودِ الدَّوَابِّ وَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ جَعَلَ لَكُمْ عِصِيًّا وَسِيَاطًا ‏","","",""],[16552,16552,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أَكَلَ أَحَدٌ مِنْكُمْ طَعَامًا أَحَبَّ إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ عَمَلِ يَدَيْهِ ‏","","",""],[16553,16553,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَالْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ الْكِنْدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلشَّهِيدِ عِنْدَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏سِتَّ خِصَالٍ ‏ ‏أَنْ يُغْفَرَ لَهُ فِي أَوَّلِ دَفْعَةٍ مِنْ دَمِهِ ‏ ‏وَيَرَى ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏وَيُرَى مَقْعَدَهُ ‏ ‏مِنْ الْجَنَّةِ ‏ ‏وَيُحَلَّى ‏ ‏حُلَّةَ ‏ ‏الْإِيمَانِ وَيُزَوَّجَ مِنْ الْحُورِ الْعِينِ ‏ ‏وَيُجَارَ ‏ ‏مِنْ عَذَابِ الْقَبْرِ وَيَأْمَنَ مِنْ الْفَزَعِ الْأَكْبَرِ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏يَوْمَ الْفَزَعِ الْأَكْبَرِ ‏ ‏وَيُوضَعَ عَلَى رَأْسِهِ تَاجُ الْوَقَارِ الْيَاقُوتَةُ مِنْهُ خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا وَيُزَوَّجَ اثْنَتَيْنِ وَسَبْعِينَ زَوْجَةً مِنْ الْحُورِ الْعِينِ وَيُشَفَّعَ فِي سَبْعِينَ إِنْسَانًا مِنْ أَقَارِبِهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[16554,16554,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُوصِيكُمْ بِالْأَقْرَبِ فَالْأَقْرَبِ ‏","","",""],[16555,16555,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏وَأَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحَرِيرِ وَالذَّهَبِ وَعَنْ ‏ ‏مَيَاثِرِ ‏ ‏النُّمُورِ ‏","","",""],[16556,16556,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ سُلَيْمٍ الْكِنَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ جَابِرٍ الطَّائِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمِقْدَامَ بْنَ مَعْدِي كَرِبَ الْكِنْدِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مَلَأَ ابْنُ ‏ ‏آدَمَ ‏ ‏وِعَاءً شَرًّا مِنْ بَطْنٍ حَسْبُ ابْنِ ‏ ‏آدَمَ ‏ ‏أُكُلَاتٌ يُقِمْنَ صُلْبَهُ فَإِنْ كَانَ لَا مَحَالَةَ فَثُلُثُ طَعَامٍ وَثُلُثُ شَرَابٍ وَثُلُثٌ لِنَفْسِهِ ‏","","",""],[16557,16557,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ الْكِنْدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يُوصِيكُمْ ‏ ‏بِأُمَّهَاتِكُمْ إِنَّ اللَّهَ يُوصِيكُمْ بِآبَائِكُمْ إِنَّ اللَّهَ يُوصِيكُمْ بِالْأَقْرَبِ فَالْأَقْرَبِ ‏","","",""],[16558,16558,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَيْسَرَةَ الْحَضْرَمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمِقْدَامَ بْنَ مَعْدِي كَرِبَ الْكِنْدِيَّ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَضُوءٍ ‏ ‏فَتَوَضَّأَ فَغَسَلَ كَفَّيْهِ ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ظَاهِرِهِمَا وَبَاطِنِهِمَا وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ‏","","",""],[16559,16559,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏قَالَ ‏ ‏وَفَدَ ‏ ‏الْمِقْدَامُ بْنُ مَعْدِي كَرِبَ ‏ ‏وَعَمْرُو بْنُ الْأَسْوَدِ ‏ ‏إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لِلْمِقْدَامِ ‏ ‏أَعَلِمْتَ أَنَّ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏تُوُفِّيَ فَرَجَّعَ ‏ ‏الْمِقْدَامُ ‏ ‏فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏أَتُرَاهَا مُصِيبَةً فَقَالَ وَلِمَ لَا أَرَاهَا مُصِيبَةً وَقَدْ وَضَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حِجْرِهِ وَقَالَ ‏ ‏هَذَا مِنِّي ‏ ‏وَحُسَيْنٌ ‏ ‏مِنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏","","",""],[16560,16560,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاسِطًا يَدَيْهِ يَقُولُ ‏ ‏مَا أَكَلَ أَحَدٌ مِنْكُمْ طَعَامًا فِي الدُّنْيَا خَيْرًا لَهُ مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدَيْهِ ‏","","",""],[16561,16561,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أَطْعَمْتَ نَفْسَكَ فَهُوَ لَكَ ‏ ‏صَدَقَةٌ ‏ ‏وَوَلَدَكَ وَزَوْجَتَكَ وَخَادِمَكَ ‏","","",""],[16562,16562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَيْكُمْ بِغِذَاءِ ‏ ‏السَّحَرِ ‏ ‏فَإِنَّهُ هُوَ الْغِذَاءُ الْمُبَارَكُ ‏","","",""],[16563,16563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْكِنْدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمِقْدَامَ بْنَ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُحُومِ الْحُمُرِ الْإِنْسِيَّةِ وَعَنْ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ ‏","","",""],[16564,16564,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَزَيْدُ بْنُ حُبَابٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمِقْدَامَ بْنَ مَعْدِي كَرِبَ ‏ ‏يَقُولُ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏أَشْيَاءَ ثُمَّ قَالَ ‏ ‏يُوشِكُ أَحَدُكُمْ أَنْ يُكَذِّبَنِي وَهُوَ مُتَّكِئٌ عَلَى ‏ ‏أَرِيكَتِهِ ‏ ‏يُحَدَّثُ بِحَدِيثِي فَيَقُولُ بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللَّهِ فَمَا وَجَدْنَا فِيهِ مِنْ حَلَالٍ اسْتَحْلَلْنَاهُ وَمَا وَجَدْنَا فِيهِ مِنْ حَرَامٍ حَرَّمْنَاهُ أَلَا وَإِنَّ مَا حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلُ مَا حَرَّمَ اللَّهُ ‏","","",""],[16565,16565,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ أَبِي كَرِيمَةَ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏الْمِقْدَامُ أَبُو كَرِيمَةَ الشَّامِيُّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَلَيْلَةُ الضَّيْفِ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَقٌّ وَاجِبَةٌ ‏ ‏فَإِنْ أَصْبَحَ بِفِنَائِهِ فَهُوَ دَيْنٌ عَلَيْهِ فَإِنْ شَاءَ اقْتَضَى وَإِنْ شَاءَ تَرَكَ ‏","","",""],[16566,16566,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَنْصُورًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ أَبِي كَرِيمَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَلَى كُلِّ مُسْلِمٍ لَلَيْلَةُ الضَّيْفِ حَقٌّ وَاجِبَةٌ فَإِنْ أَصْبَحَ بِفِنَائِهِ فَهُوَ عَلَيْهِ دَيْنٌ إِنْ شَاءَ اقْتَضَى وَإِنْ شَاءَ تَرَكَ ‏","","",""],[16567,16567,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْجُودِيِّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ الْمُهَاجِرِ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ أَبِي كَرِيمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَيُّمَا مُسْلِمٍ أَضَافَ قَوْمًا فَأَصْبَحَ الضَّيْفُ مَحْرُومًا فَإِنَّ حَقٌّ عَلَى كُلِّ مُسْلِمٍ نَصْرَهُ حَتَّى يَأْخُذَ بِقِرَى اللَّيْلَةِ لَيْلَتِهِ مِنْ زَرْعِهِ وَمَالِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو الْجُودِيِّ ‏ ‏أَخْبَرَنِي أَنَّهُ سَمِعَ ‏ ‏سَعِيدَ بْنَ الْمُهَاجِرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْمِقْدَامَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[16568,16568,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ الْكِنْدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ وَمَنْ تَرَكَ دَيْنًا أَوْ ‏ ‏ضَيْعَةً ‏ ‏فَإِلَيَّ وَأَنَا وَلِيُّ مَنْ لَا وَلِيَّ لَهُ أَفُكُّ ‏ ‏عَنْوَهُ وَأَرِثُ مَالَهُ وَالْخَالُ وَلِيُّ مَنْ لَا وَلِيَّ لَهُ يَفُكُّ عَنْهُ وَيَرِثُ مَالَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَاشِدَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ أَفُكُّ عَنْوَةً ‏","","",""],[16569,16569,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏لِمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏جَارِيَةٌ تَبِيعُ اللَّبَنَ وَيَقْبِضُ ‏ ‏الْمِقْدَامُ ‏ ‏الثَّمَنَ فَقِيلَ لَهُ سُبْحَانَ اللَّهِ أَتَبِيعُ اللَّبَنَ وَتَقْبِضُ الثَّمَنَ فَقَالَ نَعَمْ وَمَا بَأْسٌ بِذَلِكَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ لَا يَنْفَعُ فِيهِ إِلَّا الدِّينَارُ وَالدِّرْهَمُ ‏","","",""],[16570,16570,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ أَبِي كَرِيمَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَلَيْلَةُ الضَّيْفِ وَاجِبَةٌ فَإِنْ أَصْبَحَ بِفِنَائِهِ فَهُوَ دَيْنٌ لَهُ فَإِنْ شَاءَ اقْتَضَى وَإِنْ شَاءَ تَرَكَ ‏","","",""],[16571,16571,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بُدَيْلُ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ الْهَوْزَنِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ دَيْنًا أَوْ ‏ ‏ضَيْعَةً ‏ ‏فَإِلَيَّ وَمَنْ تَرَكَ مَالًا فَلِوَارِثِهِ وَأَنَا مَوْلَى مَنْ لَا مَوْلَى لَهُ أَرِثُ مَالَهُ وَأَفُكُّ ‏ ‏عَانَهُ ‏ ‏وَالْخَالُ مَوْلَى مَنْ لَا مَوْلَى لَهُ يَرِثُ مَالَهُ وَيَفُكُّ ‏ ‏عَانَهُ ‏","","",""],[16572,16572,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بُدَيْلٌ الْعُقَيْلِيُّ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ أَبِي طَلْحَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ الْهَوْزَنِيِّ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَرَكَ ‏ ‏كَلًّا ‏ ‏فَإِلَيَّ قَالَ ‏ ‏وَرُبَّمَا قَالَ إِلَى اللَّهِ وَإِلَى رَسُولِهِ ‏ ‏وَمَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ وَأَنَا وَارِثُ مَنْ لَا وَارِثَ لَهُ أَعْقِلُ عَنْهُ وَأَرِثُهُ وَالْخَالُ وَارِثُ مَنْ لَا وَارِثَ لَهُ يَعْقِلُ عَنْهُ وَيَرِثُهُ ‏","","",""],[16573,16573,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ الْأَبْرَشُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ يَحْيَى بْنِ الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْلَحْتَ يَا ‏ ‏قُدَيْمُ ‏ ‏إِنْ لَمْ تَكُنْ أَمِيرًا وَلَا جَابِيًا وَلَا عَرِيفًا ‏","","",""],[16574,16574,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعْدَ بْنَ مَرْثَدٍ الرَّحَبِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ حَوْشَبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ثَوْبَانَ بْنِ شَهْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏كُرَيْبَ بْنَ أَبْرَهَةَ ‏ ‏وَهُوَ جَالِسٌ مَعَ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏بِدَيْرِ الْمُرَّانِ ‏ ‏وَذَكَرُوا الْكِبْرَ ‏ ‏فَقَالَ ‏ ‏كُرَيْبٌ ‏ ‏سَمِعْتُ ‏ ‏أَبَا رَيْحَانَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏لَا يَدْخُلُ شَيْءٌ مِنْ الْكِبْرِ الْجَنَّةَ قَالَ فَقَالَ قَائِلٌ يَا رَسُولَ اللَّهِ إِنِّي أُحِبُّ أَنْ أَتَجَمَّلَ ‏ ‏بِسَبْقِ ‏ ‏سَوْطِي ‏ ‏وَشِسْعِ ‏ ‏نَعْلِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ذَلِكَ لَيْسَ بِالْكِبْرِ إِنَّ اللَّهَ عَزَّ وَجَلَّ جَمِيلٌ يُحِبُّ الْجَمَالَ إِنَّمَا الْكِبْرُ مَنْ سَفِهَ الْحَقَّ ‏ ‏وَغَمَصَ النَّاسَ بِعَيْنَيْهِ ‏","","",""],[16575,16575,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ مَرْثَدٍ الرَّحَبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ حَوْشَبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ثَوْبَانَ بْنِ شَهْرٍ الْأَشْعَرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏كُرَيْبَ بْنَ أَبْرَهَةَ ‏ ‏وَهُوَ جَالِسٌ مَعَ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَلَى سَرِيرِهِ ‏ ‏بِدَيْرِ الْمُرَّانِ ‏ ‏وَذَكَرَ الْكِبْرَ ‏ ‏فَقَالَ ‏ ‏كُرَيْبٌ ‏ ‏سَمِعْتُ ‏ ‏أَبَا رَيْحَانَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ شَيْءٌ مِنْ الْكِبْرِ الْجَنَّةَ فَقَالَ قَائِلٌ يَا نَبِيَّ اللَّهِ إِنِّي أُحِبُّ أَنْ أَتَجَمَّلَ بِحَبْلَانِ سَوْطِي وَشِسْعِ نَعْلِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ذَلِكَ لَيْسَ بِالْكِبْرِ إِنَّ اللَّهَ عَزَّ وَجَلَّ جَمِيلٌ يُحِبُّ الْجَمَالَ إِنَّمَا الْكِبْرُ مَنْ سَفِهَ الْحَقَّ وَغَمَصَ النَّاسَ بِعَيْنَيْهِ ‏ ‏يَعْنِي بِالْحَبْلَانِ سَيْرَ السَّوْطِ وَشِسْعَ النَّعْلِ ‏","","",""],[16576,16576,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْحُصَيْنِ الْحِمْيَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي رَيْحَانَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَلَغَنَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْوَشْرِ ‏ ‏وَالْوَشْمِ ‏ ‏وَالنَّتْفِ ‏ ‏وَالْمُشَاغَرَةِ ‏ ‏وَالْمُكَامَعَةِ ‏ ‏وَالْوِصَالِ ‏ ‏وَالْمُلَامَسَةِ ‏","","",""],[16577,16577,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُفَضَّلُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِي الْحُصَيْنِ الْهَيْثَمِ بْنِ شُفَيٍّ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏خَرَجْتُ أَنَا وَصَاحِبٌ لِي يُسَمَّى ‏ ‏أَبَا عَامِرٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْمَعَافِرِ ‏ ‏لِيُصَلِّيَ ‏ ‏بِإِيلِيَاءَ ‏ ‏وَكَانَ ‏ ‏قَاصُّهُمْ ‏ ‏رَجُلًا مِنْ ‏ ‏الْأَزْدِ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو رَيْحَانَةَ ‏ ‏مِنْ الصَّحَابَةِ قَالَ ‏ ‏أَبُو الْحُصَيْنِ ‏ ‏فَسَبَقَنِي صَاحِبِي إِلَى الْمَسْجِدِ ثُمَّ أَدْرَكْتُهُ فَجَلَسْتُ إِلَى جَنْبِهِ فَسَأَلَنِي هَلْ أَدْرَكْتَ قَصَصَ ‏ ‏أَبِي رَيْحَانَةَ ‏ ‏فَقُلْتُ لَا فَقَالَ سَمِعْتُهُ يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَشْرَةٍ عَنْ ‏ ‏الْوَشْرِ ‏ ‏وَالْوَشْمِ ‏ ‏وَالنَّتْفِ ‏ ‏وَعَنْ ‏ ‏مُكَامَعَةِ ‏ ‏الرَّجُلِ الرَّجُلَ بِغَيْرِ ‏ ‏شِعَارٍ ‏ ‏وَعَنْ ‏ ‏مُكَامَعَةِ ‏ ‏الْمَرْأَةِ الْمَرْأَةَ بِغَيْرِ ‏ ‏شِعَارٍ ‏ ‏وَأَنْ يَجْعَلَ الرَّجُلُ فِي أَسْفَلِ ثِيَابِهِ حَرِيرًا مِثْلَ الْأَعْلَامِ وَأَنْ يَجْعَلَ عَلَى مَنْكِبَيْهِ مِثْلَ ‏ ‏الْأَعَاجِمِ ‏ ‏وَعَنْ النُّهْبَى وَرُكُوبِ النُّمُورِ وَلَبُوسِ الْخَاتَمِ إِلَّا لِذِي سُلْطَانٍ ‏","","",""],[16578,16578,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَيَّاشِ بْنِ عَبَّاسٍ الْحِمْيَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حُصَيْنٍ الْحَجْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْحَجْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي رَيْحَانَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏كَرِهَ عَشْرَ خِصَالٍ ‏ ‏الْوَشْرَ ‏ ‏وَالنَّتْفَ ‏ ‏وَالْوَشْمَ ‏ ‏وَمُكَامَعَةَ ‏ ‏الرَّجُلِ الرَّجُلَ وَالْمَرْأَةِ الْمَرْأَةَ لَيْسَ بَيْنَهُمَا ثَوْبٌ ‏ ‏وَالنُّهْبَةَ ‏ ‏وَرُكُوبَ النُّمُورِ وَاتِّخَاذَ ‏ ‏الدِّيبَاجِ ‏ ‏هَاهُنَا وَهَاهُنَا أَسْفَلَ فِي الثِّيَابِ وَفِي ‏ ‏الْمَنَاكِبِ ‏ ‏وَالْخَاتَمَ إِلَّا لِذِي سُلْطَانٍ ‏","","",""],[16579,16579,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى الْأَشْيَبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي رَيْحَانَةَ ‏ ‏صَاحِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْخَاتَمِ إِلَّا لِذِي سُلْطَانٍ ‏","","",""],[16580,16580,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْكِنْدِيِّ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ نُسَىٍّ ‏ ‏عَنْ ‏ ‏أَبِي رَيْحَانَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ انْتَسَبَ إِلَى تِسْعَةِ آبَاءٍ كُفَّارٍ يُرِيدُ بِهِمْ عِزًّا وَكَرَمًا فَهُوَ عَاشِرُهُمْ فِي النَّارِ ‏","","",""],[16581,16581,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ شُرَيْحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ سُمَيْرٍ الرُّعَيْنِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا عَامِرٍ التُّجِيبِيَّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ غَيْرُهُ ‏ ‏الْجَنَبِيَّ ‏ ‏يَعْنِي غَيْرَ ‏ ‏زَيْدٍ أَبُو عَلِيٍّ الْجَنَبِيُّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا رَيْحَانَةَ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ فَأَتَيْنَا ذَاتَ لَيْلَةٍ إِلَى ‏ ‏شَرَفٍ ‏ ‏فَبِتْنَا عَلَيْهِ فَأَصَابَنَا بَرْدٌ شَدِيدٌ حَتَّى رَأَيْتُ مَنْ يَحْفِرُ فِي الْأَرْضِ حُفْرَةً يَدْخُلُ فِيهَا يُلْقِي عَلَيْهِ الْحَجَفَةَ ‏ ‏يَعْنِي التُّرْسَ ‏ ‏فَلَمَّا رَأَى ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ النَّاسِ نَادَى مَنْ يَحْرُسُنَا فِي هَذِهِ اللَّيْلَةِ وَأَدْعُو لَهُ بِدُعَاءٍ يَكُونُ فِيهِ فَضْلٌ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَا يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏ادْنُهْ ‏ ‏فَدَنَا ‏ ‏فَقَالَ مَنْ أَنْتَ فَتَسَمَّى لَهُ الْأَنْصَارِيُّ فَفَتَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالدُّعَاءِ فَأَكْثَرَ مِنْهُ قَالَ ‏ ‏أَبُو رَيْحَانَةَ ‏ ‏فَلَمَّا سَمِعْتُ مَا دَعَا بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أَنَا رَجُلٌ آخَرُ فَقَالَ ‏ ‏ادْنُهْ فَدَنَوْتُ فَقَالَ مَنْ أَنْتَ قَالَ فَقُلْتُ أَنَا ‏ ‏أَبُو رَيْحَانَةَ ‏ ‏فَدَعَا بِدُعَاءٍ هُوَ دُونَ مَا دَعَا لِلْأَنْصَارِيِّ ثُمَّ قَالَ ‏ ‏حُرِّمَتْ النَّارُ عَلَى عَيْنٍ دَمَعَتْ ‏ ‏أَوْ بَكَتْ ‏ ‏مِنْ خَشْيَةِ اللَّهِ وَحُرِّمَتْ النَّارُ عَلَى عَيْنٍ سَهِرَتْ فِي سَبِيلِ اللَّهِ ‏ ‏أَوْ قَالَ حُرِّمَتْ النَّارُ عَلَى عَيْنٍ أُخْرَى ثَالِثَةٍ لَمْ يَسْمَعْهَا ‏ ‏مُحَمَّدُ بْنُ سُمَيْرٍ ‏ ‏وَقَالَ غَيْرُهُ ‏ ‏يَعْنِي غَيْرَ ‏ ‏زَيْدٍ أَبُو عَلِيٍّ الْجَنَبِيُّ ‏","","",""],[16582,16582,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ الْقِتْبَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْحُصَيْنِ الْحَجْرِيِّ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ ‏ ‏وَصَاحِبًا لَهُ ‏ ‏يَلْزَمَانِ ‏ ‏أَبَا رَيْحَانَةَ ‏ ‏يَتَعَلَّمَانِ مِنْهُ خَيْرًا قَالَ فَحَضَرَ ‏ ‏صَاحِبِي ‏ ‏يَوْمًا وَلَمْ أَحْضُرْ ‏ ‏فَأَخْبَرَنِي ‏ ‏صَاحِبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا رَيْحَانَةَ ‏ ‏يَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ عَشْرَةً ‏ ‏الْوَشْرَ ‏ ‏وَالْوَشْمَ ‏ ‏وَالنَّتْفَ ‏ ‏وَمُكَامَعَةَ ‏ ‏الرَّجُلِ الرَّجُلَ لَيْسَ بَيْنَهُمَا ثَوْبٌ ‏ ‏وَمُكَامَعَةَ ‏ ‏الْمَرْأَةِ بِالْمَرْأَةِ لَيْسَ بَيْنَهُمَا ثَوْبٌ وَخَطَّيْ حَرِيرٍ عَلَى أَسْفَلِ الثَّوْبِ وَخَطَّيْ حَرِيرٍ عَلَى ‏ ‏الْعَاتِقَيْنِ ‏ ‏وَالنَّمِرَ ‏ ‏يَعْنِي جِلْدَةَ النَّمِرِ ‏ ‏وَالنُّهْبَةَ ‏ ‏وَالْخَاتَمَ إِلَّا لِذِي سُلْطَانٍ ‏","","",""],[16583,16583,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ جَابِرٍ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏بُسْرُ بْنُ عُبَيْدِ اللَّهِ الْحَضْرَمِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏صَاحَبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو مَرْثَدٍ الْغَنَوِيُّ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُصَلُّوا إِلَى الْقُبُورِ وَلَا تَجْلِسُوا عَلَيْهَا ‏","","",""],[16584,16584,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏بُسْرُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏بُسْرُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِدْرِيسَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا مَرْثَدٍ الْغَنَوِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَجْلِسُوا عَلَى الْقُبُورِ وَلَا تُصَلُّوا عَلَيْهَا ‏","","",""],[16585,16585,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏وَيَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏حَدَّثَنَا ‏ ‏جُبَيْرُ بْنُ نُفَيْرٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ الْجُمَعِيَّ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا اسْتَعْمَلَهُ قَبْلَ مَوْتِهِ فَسَأَلَهُ رَجُلٌ مِنْ الْقَوْمِ مَا اسْتَعْمَلَهُ قَالَ ‏ ‏يَهْدِيهِ اللَّهُ عَزَّ وَجَلَّ إِلَى الْعَمَلِ الصَّالِحِ قَبْلَ مَوْتِهِ ثُمَّ يَقْبِضُهُ عَلَى ذَلِكَ ‏","","",""],[16586,16586,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ ‏ ‏أَخْبَرَهُ ‏ ‏بَعْضُ مَنْ شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخَيْبَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ مِمَّنْ مَعَهُ إِنَّ هَذَا لَمِنْ أَهْلِ النَّارِ فَلَمَّا حَضَرَ الْقِتَالُ قَاتَلَ الرَّجُلُ أَشَدَّ الْقِتَالِ حَتَّى كَثُرَتْ بِهِ الْجِرَاحُ فَأَتَاهُ رِجَالٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ أَرَأَيْتَ الرَّجُلَ الَّذِي ذَكَرْتَ أَنَّهُ مِنْ أَهْلِ النَّارِ فَقَدْ وَاللَّهِ قَاتَلَ فِي سَبِيلِ اللَّهِ أَشَدَّ الْقِتَالِ وَكَثُرَتْ بِهِ الْجِرَاحُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنَّهُ مِنْ أَهْلِ النَّارِ وَكَادَ بَعْضُ النَّاسِ أَنْ يَرْتَابَ فَبَيْنَمَا هُمْ عَلَى ذَلِكَ وَجَدَ الرَّجُلُ أَلَمَ الْجِرَاحِ فَأَهْوَى بِيَدِهِ الرَّجُلُ إِلَى ‏ ‏كِنَانَتِهِ ‏ ‏فَانْتَزَعَ مِنْهَا سَهْمًا فَانْتَحَرَ بِهِ فَاشْتَدَّ رَجُلٌ مِنْ الْمُسْلِمِينَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ قَدْ صَدَّقَ اللَّهُ حَدِيثَكَ قَدْ انْتَحَرَ فُلَانٌ فَقَتَلَ نَفْسَهُ ‏","","",""],[16587,16587,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ رُوَيْبَةَ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏بِشْرَ بْنَ مَرْوَانَ ‏ ‏رَافِعًا يَدَيْهِ يَوْمَ الْجُمُعَةِ فَقَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ يَوْمَ ‏ ‏الْجُمُعَةِ وَمَا يَقُولُ إِلَّا هَكَذَا وَأَشَارَ بِإِصْبَعِهِ السَّبَّابَةِ ‏","","",""],[16588,16588,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عِمَارَةَ بْنِ رُوَيْبَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَنْ ‏ ‏يَلِجَ ‏ ‏النَّارَ أَحَدٌ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏مِمَّنْ سَمِعَهُ قَالَ مِنْ ‏ ‏عُمَارَةَ بْنِ رُوَيْبَةَ ‏","","",""],[16589,16589,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏أَنَّ ‏ ‏بِشْرَ بْنَ مَرْوَانَ ‏ ‏رَفَعَ يَدَيْهِ يَوْمَ الْجُمُعَةِ عَلَى الْمِنْبَرِ فَقَالَ ‏ ‏عُمَارَةُ بْنُ رُوَيْبَةَ ‏ ‏مَا زَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَذَا وَأَشَارَ بِإِصْبَعِهِ السَّبَّابَةِ ‏","","",""],[16590,16590,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ هِشَامٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عِمَارَةَ بْنِ رُوَيْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏يَلِجُ ‏ ‏النَّارَ مَنْ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا وَعِنْدَهُ رَجُلٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏فَقَالَ أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ أَشْهَدُ بِهِ عَلَيْهِ قَالَ وَأَنَا أَشْهَدُ لَقَدْ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُهُ فِي الْمَكَانِ الَّذِي سَمِعْتَهُ مِنْهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِيهِ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَارَةَ بْنِ رُوَيْبَةَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَلِجُ ‏ ‏النَّارَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[16591,16591,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ إِلَى جَنْبِ ‏ ‏عِمَارَةَ بْنِ رُوَيْبَةَ ‏ ‏وَبِشْرٌ ‏ ‏يَخْطُبُنَا فَلَمَّا دَعَا رَفَعَ يَدَيْهِ فَقَالَ ‏ ‏عِمَارَةُ ‏ ‏يَعْنِي قَبَّحَ اللَّهُ هَاتَيْنِ الْيَدَيْنِ ‏ ‏أَوْ هَاتَيْنِ الْيُدِيَّتَيْنِ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ ‏ ‏إِذَا دَعَا يَقُولُ هَكَذَا وَرَفَعَ السَّبَّابَةَ وَحْدَهَا ‏","","",""],[16592,16592,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَمْلَةَ ‏ ‏أَنَّ ‏ ‏أَبَا نَمْلَةَ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏بَيْنَمَا هُوَ جَالِسٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ رَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏هَلْ تَتَكَلَّمُ هَذِهِ الْجَنَازَةُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُ أَعْلَمُ قَالَ الْيَهُودِيُّ أَنَا أَشْهَدُ أَنَّهَا تَتَكَلَّمُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَدَّثَكُمْ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏فَلَا تُصَدِّقُوهُمْ وَلَا تُكَذِّبُوهُمْ وَقُولُوا آمَنَّا بِاللَّهِ وَكُتُبِهِ وَرُسُلِهِ فَإِنْ كَانَ حَقًّا لَمْ تُكَذِّبُوهُمْ وَإِنْ كَانَ بَاطِلًا لَمْ تُصَدِّقُوهُمْ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي نَمْلَةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏بَيْنَمَا أَنَا جَالِسٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ رَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ وَكِتَابِهِ وَرُسُلِهِ ‏","","",""],[16593,16593,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ الْأَطْوَلِ ‏ ‏قَالَ ‏ ‏مَاتَ أَخِي وَتَرَكَ ثَلَاثَ مِائَةِ دِينَارٍ وَتَرَكَ وَلَدًا صِغَارًا فَأَرَدْتُ أَنْ أُنْفِقَ عَلَيْهِمْ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخَاكَ ‏ ‏مَحْبُوسٌ ‏ ‏بِدَيْنِهِ فَاذْهَبْ فَاقْضِ عَنْهُ قَالَ فَذَهَبْتُ فَقَضَيْتُ عَنْهُ ثُمَّ جِئْتُ فَقُلْتُ يَا رَسُولَ اللَّهِ قَدْ قَضَيْتُ عَنْهُ وَلَمْ يَبْقَ إِلَّا امْرَأَةً ‏ ‏تَدَّعِي دِينَارَيْنِ وَلَيْسَتْ لَهَا بَيِّنَةٌ قَالَ أَعْطِهَا فَإِنَّهَا صَادِقَةٌ ‏","","",""],[16594,16594,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏مَرَّتَيْنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزَّعْرَاءِ عَمْرُو بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَعَّدَ فِيَّ النَّظَرَ وَصَوَّبَ وَقَالَ أَرَبُّ إِبِلٍ أَنْتَ أَوْ رَبُّ غَنَمٍ قَالَ مِنْ كُلٍّ قَدْ آتَانِي اللَّهُ فَأَكْثَرَ وَأَطْيَبَ قَالَ فَتُنْتِجُهَا وَافِيَةً أَعْيُنُهَا وَآذَانُهَا ‏ ‏فَتَجْدَعُ ‏ ‏هَذِهِ فَتَقُولُ ‏ ‏صَرْمَاءَ ‏ ‏ثُمَّ تَكَلَّمَ ‏ ‏سُفْيَانُ ‏ ‏بِكَلِمَةٍ لَمْ أَفْهَمْهَا ‏ ‏وَتَقُولُ بَحِيرَةَ اللَّهِ فَسَاعِدُ اللَّهِ أَشَدُّ ‏ ‏وَمُوسَاهُ ‏ ‏أَحَدُّ وَلَوْ شَاءَ أَنْ يَأْتِيَكَ بِهَا ‏ ‏صَرْمَاءَ ‏ ‏أَتَاكَ قُلْتُ إِلَى مَا تَدْعُو قَالَ إِلَى اللَّهِ وَإِلَى الرَّحِمِ قُلْتُ يَأْتِينِي الرَّجُلُ مِنْ بَنِي عَمِّي فَأَحْلِفُ أَنْ لَا أُعْطِيَهُ ثُمَّ أُعْطِيهِ قَالَ ‏ ‏فَكَفِّرْ عَنْ يَمِينِكَ وَأْتِ الَّذِي هُوَ خَيْرٌ أَرَأَيْتَ لَوْ كَانَ لَكَ عَبْدَانِ أَحَدُهُمَا يُطِيعُكَ وَلَا يَخُونُكَ وَلَا يَكْذِبُكَ وَالْآخَرُ يَخُونُكَ وَيَكْذِبُكَ قَالَ قُلْتُ لَا بَلْ الَّذِي لَا يَخُونُنِي وَلَا يَكْذِبُنِي وَيَصْدُقُنِي الْحَدِيثَ أَحَبُّ إِلَيَّ قَالَ كَذَاكُمْ أَنْتُمْ عِنْدَ رَبِّكُمْ عَزَّ وَجَلَّ ‏","","",""],[16595,16595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيَّ ‏ ‏شَمْلَةٌ ‏ ‏أَوْ ‏ ‏شَمْلَتَانِ ‏ ‏فَقَالَ لِي هَلْ لَكَ مِنْ مَالٍ قُلْتُ نَعَمْ قَدْ آتَانِي اللَّهُ عَزَّ وَجَلَّ مِنْ كُلِّ مَالِهِ مِنْ خَيْلِهِ وَإِبِلِهِ وَغَنَمِهِ وَرَقِيقِهِ فَقَالَ ‏ ‏فَإِذَا آتَاكَ اللَّهُ مَالًا فَلْيَرَ عَلَيْكَ نِعْمَتَهُ فَرُحْتُ إِلَيْهِ فِي ‏ ‏حُلَّةٍ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ وَمَعْنَاهُ قَالَ فَغَدَوْتُ إِلَيْهِ فِي حُلَّةٍ حَمْرَاءَ ‏","","",""],[16596,16596,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مَالِكٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ الرَّجُلُ أَمُرُّ بِهِ فَلَا يُضَيِّفُنِي وَلَا ‏ ‏يَقْرِينِي ‏ ‏فَيَمُرُّ بِي ‏ ‏فَأَجْزِيهِ قَالَ لَا بَلْ ‏ ‏اقْرِهِ ‏ ‏قَالَ فَرَآنِي ‏ ‏رَثَّ ‏ ‏الْهَيْئَةِ فَقَالَ هَلْ لَكَ مِنْ مَالٍ فَقُلْتُ قَدْ أَعْطَانِي اللَّهُ عَزَّ وَجَلَّ مِنْ كُلِّ الْمَالِ مِنْ الْإِبِلِ وَالْغَنَمِ قَالَ ‏ ‏فَلْيُرَ أَثَرُ نِعْمَةِ اللَّهِ عَلَيْكَ ‏","","",""],[16597,16597,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الزَّعْرَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مَالِكِ بْنِ نَضْلَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَيْدِي ثَلَاثَةٌ فَيَدُ اللَّهِ الْعُلْيَا وَيَدُ الْمُعْطِي الَّتِي تَلِيهَا وَيَدُ السَّائِلِ السُّفْلَى ‏ ‏فَأَعْطِيَنَّ الْفَضْلَ وَلَا تَعْجَزْ عَنْ نَفْسِكَ ‏","","",""],[16598,16598,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شَيْبَانَ ‏ ‏قَالَ ‏ ‏أَتَانَا ‏ ‏ابْنُ مِرْبَعٍ الْأَنْصَارِيُّ ‏ ‏وَنَحْنُ فِي مَكَانٍ مِنْ الْمَوْقِفِ بَعِيدٍ فَقَالَ إِنِّي رَسُولُ رَسُولِ اللَّهِ إِلَيْكُمْ يَقُولُ ‏ ‏كُونُوا عَلَى ‏ ‏مَشَاعِرِكُمْ ‏ ‏هَذِهِ فَإِنَّكُمْ عَلَى ‏ ‏إِرْثٍ ‏ ‏مِنْ ‏ ‏إِرْثِ ‏ ‏إِبْرَاهِيمَ ‏ ‏لِمَكَانٍ تَبَاعَدَهُ ‏ ‏عَمْرٌو ‏","","",""],[16599,16599,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏الْمِسْوَرَ بْنَ مَخْرَمَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَمْرَو بْنَ عَوْفٍ ‏ ‏وَهُوَ حَلِيفُ ‏ ‏بَنِي عَامِرِ بْنِ لُؤَيٍّ ‏ ‏وَكَانَ شَهِدَ ‏ ‏بَدْرًا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏إِلَى ‏ ‏الْبَحْرَيْنِ ‏ ‏يَأْتِي ‏ ‏بِجِزْيَتِهَا ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ صَالَحَ أَهْلَ ‏ ‏الْبَحْرَيْنِ ‏ ‏وَأَمَّرَ عَلَيْهِمْ ‏ ‏الْعَلَاءَ بْنَ الْحَضْرَمِيِّ ‏ ‏فَقَدِمَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏بِمَالٍ مِنْ ‏ ‏الْبَحْرَيْنِ ‏ ‏فَسَمِعَتْ ‏ ‏الْأَنْصَارُ ‏ ‏بِقُدُومِهِ ‏ ‏فَوَافَتْ ‏ ‏صَلَاةَ الْفَجْرِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْفَجْرِ انْصَرَفَ فَتَعَرَّضُوا لَهُ فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ رَآهُمْ فَقَالَ أَظُنُّكُمْ قَدْ سَمِعْتُمْ أَنَّ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏قَدْ جَاءَ وَجَاءَ بِشَيْءٍ قَالُوا أَجَلْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَأَبْشِرُوا وَأَمِّلُوا مَا يَسُرُّكُمْ فَوَاللَّهِ مَا الْفَقْرَ أَخْشَى عَلَيْكُمْ وَلَكِنِّي أَخْشَى أَنْ تُبْسَطَ الدُّنْيَا عَلَيْكُمْ كَمَا بُسِطَتْ عَلَى مَنْ كَانَ قَبْلَكُمْ فَتَنَافَسُوهَا كَمَا تَنَافَسُوهَا ‏ ‏وَتُلْهِيكُمْ ‏ ‏كَمَا ‏ ‏أَلْهَتْهُمْ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏الْمِسْوَرَ بْنَ مَخْرَمَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَمْرَو بْنَ عَوْفٍ ‏ ‏وَهُوَ حَلِيفُ ‏ ‏بَنِي عَامِرِ بْنِ لُؤَيٍّ ‏ ‏وَكَانَ شَهِدَ ‏ ‏بَدْرًا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[16600,16600,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الْمِنْهَالِ ‏ ‏سَمِعَ ‏ ‏إِيَاسَ بْنَ عَبْدٍ الْمُزَنِيَّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبِيعُوا الْمَاءَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الْمَاءِ ‏ ‏لَا يَدْرِي ‏ ‏عَمْرٌو ‏ ‏أَيَّ مَاءٍ هُوَ ‏","","",""]];
